	@Override
	public List<StateBean> fetchStates() {

		try {
			List<State> list = stateRepository.findByEnabled((short) 1);

			List<StateBean> beanList = new ArrayList<>();
			for (State state : list) {
				beanList.add(convertStateEntityToBean(state));
			}
			return beanList;
		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return null;
		}
	}

	private StateBean convertStateEntityToBean(State entity) {

		StateBean bean = new StateBean();
		if (entity != null) {
			bean.setStateId(entity.getStateId());
			bean.setStateName(entity.getStateName());
			bean.setStateNameH(entity.getStateNameH());
			bean.setEnabled(entity.getEnabled());
		}
		return bean;
	}

