	private OfficeBean convertOfficeEntityToBean(Office entity) {

		OfficeBean bean = new OfficeBean();
		if (entity != null) {
			bean.setId(entity.getId());
			bean.setOfficeName(entity.getOfficeName());
			bean.setOfficeNameH(entity.getOfficeNameH());
			bean.setOfficeType(convertOfficeTypeEntityToBean(entity.getOfficeType()));
			if (entity.getParentOffice() != null)
				bean.setParentOffice(convertOfficeEntityToBean(entity.getParentOffice()));
			// bean.setOic(con);
			bean.setDivision(convertDivisionEntityToBean(entity.getDivision()));
			if (entity.getDistrictCode() != null)
				bean.setDistrict(convertDistrictEntityToBean(
						districtRepository.findByDistrictCodeAndEnabled(entity.getDistrictCode(), (short) 1)));
			bean.setEnabled(entity.getEnabled());

			bean.setOfficeAddress(entity.getOfficeAddress());

		}
		return bean;
	}

	private OfficeBean convertOfficeEntToBean(Office entity) {

		OfficeBean bean = new OfficeBean();
		if (entity != null) {
			bean.setId(entity.getId());
			bean.setExeOfficeId(entity.getId());
			bean.setOfficeName(entity.getOfficeName());
			bean.setOfficeNameH(entity.getOfficeNameH());

		}
		return bean;
	}

	// Rakesh
	private OfficeBean convertOfficeEntityToBeanNew(Office entity, List<SqmAllocation> allocations) {

		OfficeBean bean = new OfficeBean();
		if (entity != null) {
			bean.setId(entity.getId());
			bean.setExeOfficeId(entity.getId());
			bean.setOfficeName(entity.getOfficeName());
			bean.setOfficeNameH(entity.getOfficeNameH());
			bean.setOfficeType(convertOfficeTypeEntityToBean(entity.getOfficeType()));
			bean.setParentOffice(convertOfficeEntityToBean(entity.getParentOffice()));
			// bean.setOic(con);
			bean.setDivision(convertDivisionEntityToBean(entity.getDivision()));
			bean.setDistrict(convertDistrictEntityToBean(
					districtRepository.findByDistrictCodeAndEnabled(entity.getDistrictCode(), (short) 1)));
			bean.setEnabled(entity.getEnabled());

			bean.setOfficeAddress(entity.getOfficeAddress());
			// String allSqmSelectedOffices="";
			// new code
			for (SqmAllocation allocation : allocations) {
				if (allocation.getOfficeId().equals(entity.getId())) {
					bean.setIsSqmChecked(1);

					// allSqmSelectedOffices+=allocation.getOfficeId()+",";
					break;
				} else {

					bean.setIsSqmChecked(0);
					// break;
				}
			}
		}
//		if(bean.getIsSqmChecked()==1)
//	
		return bean;
	}

