	private ContractorBean convertContractorEntityToBean1(Contractor entity) {

		ContractorBean bean = new ContractorBean();
		if (entity != null) {
			bean.setId(entity.getId());
			String registrationNo = "";
			if (null != entity.getRegistrationNumber()) {
				registrationNo = entity.getRegistrationNumber();
			} else if (null != entity.getContractorId()) {
				registrationNo = entity.getContractorId();
			}
			bean.setName(registrationNo + " - " + entity.getName());
			bean.setPan(entity.getPan());
			bean.setGstin(entity.getGstin());
			bean.setAddress(entity.getAddress());

		}
		return bean;

	}

	private Contractor convertContractorBeanToEntity(Contractor entity, ContractorBean bean) {
		if (bean != null) {
			entity.setAddress(bean.getAddress());
			entity.setContactNo(bean.getContactNo());
			entity.setDistrict(bean.getDistrict());
			entity.setEmailId(bean.getEmailId());
			entity.setGstin(bean.getGstin());
			entity.setId(bean.getId());
			entity.setName(bean.getName());
			entity.setPan(bean.getPan());
			entity.setState(bean.getState());
			entity.setRegistrationNumber(bean.getRegistrationNumber());
			entity.setFatherName(bean.getFatherName());
			entity.setContractorId(bean.getContractorId());
		}
		return entity;

	}

	private WorkBean convertWorkEntityToBean(Work entity) {
		WorkBean bean = new WorkBean();
		if (entity != null) {
			bean.setWorkRequisitionNo(entity.getWorkRequisitionNo());
			bean.setWorkRequisitionDate(RESUtil.convertDateToString(entity.getCreatedDate()));
			bean.setIsLegacy(entity.getIsLegacy());
			bean.setBillingFlag(entity.getBillingFlag());
			bean.setWorkId(entity.getId());
			bean.setWorkName(entity.getWorkName());
			if (entity.getWorkNatureId() != null && entity.getWorkNatureId().getWorkNatureId() != null)
				bean.setWorkNatureId(entity.getWorkNatureId().getWorkNatureId());
			bean.setWorkTypeId(entity.getWorkTypeId().getWorkTypeId());
			if (entity.getMaxBillingAmount() != null) {
				bean.setMaxBillingAmount(entity.getMaxBillingAmount());
			}
			bean.setWorkTypeName(entity.getWorkTypeId().getWorkTypeNameE());
			if (entity.getWorkSubTypeId() != null)
				bean.setWorkSubTypeId(entity.getWorkSubTypeId().getWorkSubTypeId());
			if (null != entity.getSchemeTypeId())
				bean.setSchemeTypeId(entity.getSchemeTypeId().getId());

			bean.setDistance(entity.getDistance());
			if (entity.getCompleteddistance() != null) {
				bean.setCompleteddistance(entity.getCompleteddistance());
			}

			if (entity.getLineDepartmentId() != null) {
				bean.setLineDepartmentId(entity.getLineDepartmentId().getLineDepartmentId());

				bean.setLineDepartmentName(entity.getLineDepartmentId().getLineDepartmentNameE());
			}

			if (entity.getWorkStatusId() != null) {
				bean.setWorkStatusId(entity.getWorkStatusId().getId());
				bean.setWorkStatus(entity.getWorkStatusId().getWorkStatusNameE());
			}

			if (entity.getWorkRequestStatusId() != null) {
				bean.setWorkRequestStatusId(entity.getWorkRequestStatusId().getId());
				bean.setWorkRequestStatus(entity.getWorkStatusId().getWorkStatusNameE());
			}
		}

		bean.setWorkTypeBean(convertWorkTypeEntityToBean(entity.getWorkTypeId()));
		bean.setWorkSubTypeBean(convertWorkSubTypeEntityToBean(entity.getWorkSubTypeId()));
		bean.setLineDepartmentBean(convertLineDepartmentEntityToBean(entity.getLineDepartmentId()));

		if (entity.getEstimatedCost() != null) {
			bean.setEstimatedCostString(String.valueOf(entity.getEstimatedCost()));
		}

		if (entity.getTotalCost() != null) {
			bean.setTotalCostString(String.valueOf(entity.getTotalCost()));
		}

		if (entity.getAccountHead() != null) {
			bean.setAccountHeadId(entity.getAccountHead().getId());
			bean.setAccountHeadName(entity.getAccountHead().getAccountHeadNameE());
		}

		bean.setAgencyTypeId(entity.getAgencyTypeId().getAgencyTypeId());
		bean.setAgencyTypeBean(convertAgencyTypeEntityToBean(entity.getAgencyTypeId()));
		bean.setAgencyName(entity.getAgencyTypeId().getAgencyTypeNameE());

		if (entity.getTotalExpenditureTill31March2018() != null)
			bean.setTotalExpenditureTill31March2018String(String.valueOf(entity.getTotalExpenditureTill31March2018()));

		bean.setTotalExpenditureOnContingencyTill31March2018(entity.getTotalExpenditureOnContingencyTill31March2018());

		if (entity.getPhysicalStageType() != null) {
			bean.setPhysicalStageId(entity.getPhysicalStageType().getPhysicalStageId());
			bean.setPhysicalStageType(entity.getPhysicalStageType().getPhysicalStageNameE());
		}
		if (null != entity.getTotalExpenditureTill31March2018()) {
			bean.setTotalExpenditureTill31March2018String(String.valueOf(entity.getTotalExpenditureTill31March2018()));
		}

		if (entity.getTotalExpenditureTill31March2018() != null) {
			bean.setTotalExpenditureTill31March2018String(String.valueOf(entity.getTotalExpenditureTill31March2018()));
		}

		if (entity.getPhysicalStageType() != null) {

			bean.setPhysicalStageId(entity.getPhysicalStageType().getPhysicalStageId());
		}
		if (entity.getTentativeCompletionDate() != null)
			bean.setTentativeCompletionDateString(RESUtil.convertDateToString(entity.getTentativeCompletionDate()));

		if (entity.getTotalAmountRecievedTill31march2018() != null)
			bean.setTotalAmountRecievedTill31March2018String(
					String.valueOf(entity.getTotalAmountRecievedTill31march2018()));

		if (entity.getAssistantEngineer() != null) {
			bean.setAssistantEngineerId(entity.getAssistantEngineer().getId());
			bean.setAssistantEngineer(userService.fetchUserDetailsByUserName(entity.getAssistantEngineer().getName()));
			bean.setAssistantEngineerName(entity.getAssistantEngineer().getName());
		}

		if (entity.getAssistantEngineer() != null) {
			String name = entity.getAssistantEngineer().getName();
			String post = entity.getAssistantEngineer().getDesignation().getDesignation();
			bean.setAdhikariNameNPost(name + "-" + post);

		}

		if (entity.getSubDivisionalOfficer() != null) {
			bean.setSubDivisionOfficerId(entity.getSubDivisionalOfficer().getId());
			bean.setSubDivisionOfficer(
					userService.fetchUserDetailsByUserName(entity.getSubDivisionalOfficer().getName()));
			bean.setSubDivisionOfficerName(entity.getSubDivisionalOfficer().getName());
		}

		if (entity.getSubDivisionalOfficer() != null) {
			String name = entity.getSubDivisionalOfficer().getName();
			String post = entity.getSubDivisionalOfficer().getDesignation().getDesignation();
			bean.setAdhikariNameNPost(name + "-" + post);

		}

		if (entity.getSubEngineer() != null) {
			bean.setSubEngineerId(entity.getSubEngineer().getId());
			bean.setSubEngineer(userService.fetchUserDetailsByUserName(entity.getSubEngineer().getName()));
			bean.setSubEngineerName(entity.getSubEngineer().getName());
		}

		if (entity.getSubDivisionalOfficer() != null) {

			bean.setSubDivisionOfficerId(entity.getSubDivisionalOfficer().getId());
			bean.setSubDivisionOfficer(
					userService.fetchUserDetailsByUserName(entity.getSubDivisionalOfficer().getUsername()));
			bean.setSubDivisionOfficerName(entity.getSubDivisionalOfficer().getName());
		}

		bean.setExecutiveEngineerOfficeId(entity.getExecutiveEngineerOffice().getId());
		bean.setExecutiveEngineerOfficeName(entity.getExecutiveEngineerOffice().getOfficeName());

		bean.setChiefEngineerOfficeName(entity.getChiefEngineerOffice().getOfficeName());
		bean.setSuperintendingEngineerOfficeName(entity.getSuperintendingEngineerOffice().getOfficeName());
		bean.setDistrictName(entity.getDistrict().getDistrictName());

		bean.setWorkRequisitionNo(entity.getWorkRequisitionNo());
		bean.setModifiedBy(entity.getModifiedBy());

		bean.setLetterNo(entity.getLetterNo());
		if (entity.getLetterDate() != null)
			bean.setLetterDateString(RESUtil.convertDateToString(entity.getLetterDate()));

		if (entity.getLineDepartmentFile() != null)
			bean.setLineDepartmentFileId(entity.getLineDepartmentFile().getDocumentId());

		if (entity.getKmlFileUpload() != null)
			bean.setKmlFileId(entity.getKmlFileUpload().getDocumentId());

		bean.setDistrictId(entity.getDistrict().getDistrictId());
		bean.setDistrictName(entity.getDistrict().getDistrictNameH());
		bean.setBlockId(entity.getBlock().getBlockId());
		bean.setBlockName(entity.getBlock().getBlockNameH());
		if (entity.getGramPanchayat() != null)
			bean.setGramPanchayatId(entity.getGramPanchayat().getGramPanchayatId());
		bean.setGramPanchayatName(entity.getGramPanchayat().getGpNameH());
		if (entity.getVillage() != null)
			bean.setVillageId(entity.getVillage().getId());

		bean.setVillageBean(convertVillageEntityToBean(entity.getVillage()));
		bean.setLocationAddress(entity.getLocationAddress());
		bean.setLocationGeometery(entity.getLocationGeometery());
		bean.setWorkLocationLatitude(entity.getWorkLocationLatitude());
		bean.setWorkLocationLongitude(entity.getWorkLocationLongitude());
		bean.setClientIp(entity.getClientIp());
		bean.setApprovedBy(entity.getApprovedBy());
		bean.setStatus(entity.getStatus());
		bean.setAgreementDateString(RESUtil.convertDateToString(entity.getAgreementDate()));
		bean.setContractorBean(convertContractorEntityToBean1(entity.getContractor()));
		bean.setTenderedRateSign(entity.getTenderedRateSign());
		bean.setTenderedRatePer(entity.getTenderedRatePer());
		bean.setTenderCost(entity.getTenderCost());
		bean.setWorkRequestStatusId(entity.getWorkRequestStatusId().getId());
		bean.setWorkRequestStatus(entity.getWorkRequestStatusId().getStatusNameE());
		bean.setRemarks(entity.getRemarks());
		bean.setProbableAmountOfWork(entity.getProbableAmountOfWork());

		if (entity.getPacAmount() != null)
			bean.setPacAmount(entity.getPacAmount());
		if (entity.getAgreementCopy() != null)
			bean.setAgreementCopyId(entity.getAgreementCopy().getDocumentId());
		bean.setAgreementNumber(entity.getAgreementNumber());

		if (entity.getIsLegacy() == 1) {
			if (entity.getContractor() != null) {
				bean.setContractorId(entity.getContractor().getId());
				bean.setContractorName(entity.getContractor().getName());
				bean.setProbableAmountOfWork(entity.getProbableAmountOfWork());
			}
		} else {
			WorkTender workTender = (workTenderRepository.findByWorkIdOrderByCreatedDateDesc(entity.getId()).size() > 0
					? workTenderRepository.findByWorkIdOrderByCreatedDateDesc(entity.getId()).get(0)
					: null);
			if (workTender != null) {
				bean.setContractorId(workTender.getContractorId().getId());
				bean.setContractorName(workTender.getContractorId().getName());
				bean.setContractorBean(convertContractorEntityToBean(workTender.getContractorId()));
				bean.setProbableAmountOfWork(workTender.getAmountOfContract());
			}
		}

		List<AdministrationSanctionBean> administrationSanctionBeanList = fetchAdministrativeDetailsListByWorkId(
				entity.getId());
		bean.setAdministrationSanctionBeanList(administrationSanctionBeanList);

		List<TechnicalSanctionBean> technicalSanctionBeanList = fetchTechnicalDetailsListByWorkId(entity.getId());
		bean.setTechnicalSanctionBeanList(technicalSanctionBeanList);

		TechnicalSanction entityTechnical = (technicalSanctionRepository.findAllTSByWork(entity).size() > 0
				? technicalSanctionRepository.findAllTSByWork(entity).get(0)
				: null);
		AdministrationSanction entityAdministration = (administrationSanctionRepository.findAllASByWork(entity)
				.size() > 0 ? administrationSanctionRepository.findAllASByWork(entity).get(0) : null);

		if (entityTechnical != null) {
			bean.setTechnicalSanctionId(entityTechnical.getId());

			bean.setTechnicalSanctionBean(convertTechnicalSanctionEntityToBean(entityTechnical));

			if (entityTechnical.getTechnicalSanctionType() != null
					&& entityTechnical.getTechnicalSanctionType().getTechnicalSanctionTypeId() != null)
				bean.setTechnicalSanctionTypeId(
						entityTechnical.getTechnicalSanctionType().getTechnicalSanctionTypeId());

			if (entityTechnical.getTechnicalSanctionType() != null
					&& entityTechnical.getTechnicalSanctionType().getTechnicalSanctionType() != null)
				bean.setTechnicalSanctionType(entityTechnical.getTechnicalSanctionType().getTechnicalSanctionType());

			bean.setTechnicalSanctionNo(entityTechnical.getTechnicalSanctionNo());
			bean.setTsDispatchNumber(entityTechnical.getTsDispatchNumber());

			if (entity.getIsLegacy() == 1) {
				bean.setTechnicalSanctionAmount(entityTechnical.getTechnicalSanctionAmount());
			} else {
				bean.setTechnicalSanctionAmount(entityTechnical.getWorkEstimation().getGrandTotal());
			}

			if (entityTechnical.getTsIssuingAuthority() != null)
				bean.setTsIssuingAuthorityName(entityTechnical.getTsIssuingAuthority().getDesignation());

			if (entityTechnical.getTechnicalSanctionDate() != null)
				bean.setTechnicalSanctionDate(RESUtil.convertDateToString(entityTechnical.getTechnicalSanctionDate()));
			if (entityTechnical.getDocumentUploadTechnical() != null
					&& entityTechnical.getDocumentUploadTechnical().getDocumentId() != null)
				bean.setTechnicalSanctionFileId(entityTechnical.getDocumentUploadTechnical().getDocumentId());
			if (entityTechnical.getDocumentUploadDrawing() != null
					&& entityTechnical.getDocumentUploadDrawing().getDocumentId() != null)
				bean.setLatestDrawingCopyId(entityTechnical.getDocumentUploadDrawing().getDocumentId());
			if (entityTechnical.getDocumentUploadEstimate() != null
					&& entityTechnical.getDocumentUploadEstimate().getDocumentId() != null)
				bean.setEstimateFileId(entityTechnical.getDocumentUploadEstimate().getDocumentId());
			bean.setTsAuthorityName(entityTechnical.getTsAuthorityName());
			if (entityTechnical.getTsIssuingAuthority() != null)
				bean.setTsIssuingAuthorityId(entityTechnical.getTsIssuingAuthority().getId());

			if (entityTechnical.getTechnicalStatus() != null && entityTechnical.getTechnicalStatus().getId() != null) {
				bean.setTechnicalSanctionStatusId(entityTechnical.getTechnicalStatus().getId());
			}
			/*
			 * if (entityTechnical.getTechnicalSanctionStatusId()!= null)
			 * bean.setTechnicalSanctionStatusId(entityTechnical.
			 * getTechnicalSanctionStatusId());
			 */

			bean.setIsEeOfficeName(entityTechnical.getIsEeOfficeName());
			bean.setIsSeOfficeName(entityTechnical.getIsSeOfficeName());
			bean.setIsCeOfficeName(entityTechnical.getIsCeOfficeName());
			bean.setIsDistrictName(entityTechnical.getIsDistrictName());
			bean.setIsGrampanchayatName(entityTechnical.getIsGrampanchayatName());
			bean.setIsLinedepartmentName(entityTechnical.getIsLinedepartmentName());

		}
		if (entityAdministration != null) {

			bean.setAdministrationSanctionId(entityAdministration.getId());

			if (entityAdministration.getAdministrationSanctionType() != null
					&& entityAdministration.getAdministrationSanctionType().getAdministrationSanctionTypeId() != null) {
				bean.setAdministrationSanctionTypeId(
						entityAdministration.getAdministrationSanctionType().getAdministrationSanctionTypeId());

				if (entityAdministration.getAdministrationSanctionType() != null
						&& entityAdministration.getAdministrationSanctionType().getAdministrationSanctionType() != null)
					bean.setAdministrationSanctionType(
							entityAdministration.getAdministrationSanctionType().getAdministrationSanctionType());
			}
			bean.setAdministrationSanctionNo(entityAdministration.getAdministrativeSanctionNo());
			bean.setAdministrationSanctionAmount(entityAdministration.getAdministrativeSanctionAmount());
			bean.setAdministrationSanctionDate(
					RESUtil.convertDateToString(entityAdministration.getAdministrativeSanctionDate()));
			if (entityAdministration.getIssuingAuthority() != null)
				bean.setIssuingAuthorityId(entityAdministration.getIssuingAuthority().getIssuingAuthorityId());
			if (entityAdministration.getDocumentUpload() != null)
				bean.setAdministrationSanctionFileId(entityAdministration.getDocumentUpload().getDocumentId());
			bean.setAsAuthorityName(entityAdministration.getAsAuthorityName());

			bean.setContingencyAmount(entityAdministration.getContingencyAmount());

			if (entityAdministration.getIssuingAuthority() != null)
				bean.setAsIssuingAuthorityName(entityAdministration.getIssuingAuthority().getIssuingAuthorityName());

			bean.setTotalCost(entityAdministration.getAdministrativeSanctionAmount());
			bean.setTotalCostString(entityAdministration.getAdministrativeSanctionAmount() + "");

		}

		WorkEstimationBean workEstimationBean = fetchWorkEstimationDetailsById(entity.getId());
		if (workEstimationBean != null) {
			bean.setContingencyAmount(new BigDecimal(workEstimationBean.getWorkChargeContingencyAmt()));
		}

		// WorkTender workTender = workTenderRepository.findByWorkId(entity.getId());
		WorkTender workTender = workTenderRepository.findByWorkIdOrderByCreatedDateDesc(entity.getId()).size() > 0
				? workTenderRepository.findByWorkIdOrderByCreatedDateDesc(entity.getId()).get(0)
				: null;
		if (workTender != null) {
			bean.setPacAmount(workTender.getAmountOfContract());
			bean.setTenderCost(workTender.getTenderCost());
			bean.setTenderedRateSign(workTender.getTenderedRateSign());
			bean.setTenderedRatePer(new BigDecimal(workTender.getTenderedRate()));
		}

		// WorkAgreementBean workAgreementBean =
		// workAgreementServiceImpl.fetchWorkAgreementDetails(entity.getId(), false);
		// WorkAgreement workAgreement = workAgreementRepository.findByWork(entity);
		WorkAgreement workAgreement = workAgreementRepository.findByWorkOrderByCreatedDateDesc(entity).size() > 0
				? workAgreementRepository.findByWorkOrderByCreatedDateDesc(entity).get(0)
				: null;
		if (workAgreement != null) {
			bean.setWrittenOrderDate(RESUtil.convertDateToString(workAgreement.getWritten_order_date()));
			bean.setAgreementNumber(workAgreement.getAgreementNumber());
			bean.setAgreementDateString(RESUtil.convertDateToString(workAgreement.getAgreementDate()));
			bean.setTentativeCompletionDateString(
					RESUtil.convertDateToString(workAgreement.getTentativeCompletionDate()));

			WorkAgreementBean workAgreementBean = workAgreementServiceImpl.fetchWorkAgreementDetails(entity.getId(),
					true);
			bean.setWorkAgreementBean(workAgreementBean);
		}

		BigDecimal administrativeSanctionAmount = new BigDecimal(0);

		if (entityAdministration != null) {
			bean.setAdministrationSanctionAmount(entityAdministration.getAdministrativeSanctionAmount());
			administrativeSanctionAmount = entityAdministration.getAdministrativeSanctionAmount();
		} else {
			bean.setAdministrationSanctionAmount(administrativeSanctionAmount);
		}
		List<Bill> billList = billRepository.findByWorkAndStatusStatusIdNotIn(entity,
				RESConstants.STATUS_FINAL_BILL_REJECTED_ID);

		List<BillBean> billBeanList = new ArrayList<BillBean>();
		BillBean billBean = null;
		BigDecimal expenditureAmountTotal = new BigDecimal(0);
		BigDecimal billAmount = new BigDecimal(0);

		for (Bill bill : billList) {
			billBean = new BillBean();
			billBean.setId(bill.getId());
			billBean.setBillNo(bill.getBillNo());
			billBean.setBillDate(RESUtil.convertDateToString(bill.getBillDate()));
			billBean.setBillType(bill.getBillType());
			billBean.setBillAmount(bill.getBillAmount());

			billBeanList.add(billBean);
			expenditureAmountTotal = expenditureAmountTotal.add(bill.getBillAmountWithoutDeduction());
		}

		// bean.setBillList(billBeanList);

		BigDecimal totalExpTill31March2018 = new BigDecimal(0);
		BigDecimal totalExpOnContTill31March2018 = new BigDecimal(0);

		if (entity.getTotalExpenditureTill31March2018() != null) {
			totalExpTill31March2018 = entity.getTotalExpenditureTill31March2018();
		}

		if (entity.getTotalExpenditureOnContingencyTill31March2018() != null) {
			totalExpOnContTill31March2018 = entity.getTotalExpenditureOnContingencyTill31March2018();
		}

		// Will be null in case of non legacy
		// if(entity.getTotalExpenditureTill31March2018() != null &&
		// entity.getTotalExpenditureOnContingencyTill31March2018() != null) {
		expenditureAmountTotal = (totalExpTill31March2018.subtract(totalExpOnContTill31March2018))
				.add(expenditureAmountTotal);
		// }

		bean.setExpenditureAmountTotal(expenditureAmountTotal);
		List<ContengencyTable> contengencyTableList = contengencyRepository.findByWork(entity);

		BigDecimal contingencyAmountTotal = new BigDecimal(0);
		for (ContengencyTable contengencyTable : contengencyTableList) {
			contingencyAmountTotal = contingencyAmountTotal
					.add(new BigDecimal(contengencyTable.getExpenditureAmount()));
		}

		if (entity.getTotalExpenditureOnContingencyTill31March2018() != null) {
			contingencyAmountTotal = entity.getTotalExpenditureOnContingencyTill31March2018()
					.add(contingencyAmountTotal);
		}
		bean.setContingencyAmountTotal(contingencyAmountTotal);

		bean.setRemainingAmountTotal(
				administrativeSanctionAmount.subtract(expenditureAmountTotal).subtract(contingencyAmountTotal));

		// CCDetails ccDetails = ccDetailsRepository.findByWork(entity);
		CCDetails ccDetails = ccDetailsRepository.findByWorkOrderByCreatedDateDesc(entity).size() > 0
				? ccDetailsRepository.findByWorkOrderByCreatedDateDesc(entity).get(0)
				: null;
		if (ccDetails != null) {
			bean.setWorkCompletedOn(RESUtil.convertDateToString(ccDetails.getWorkCompletedOn()));
			bean.setUsedMBNo(ccDetails.getUsedMBNo());
			bean.setTakenOverOn(RESUtil.convertDateToString(ccDetails.getTakenOverOn()));
			bean.setPageNo(ccDetails.getPageNo());
			bean.setMbNo(ccDetails.getMbNo());
			bean.setDate(RESUtil.convertDateToString(ccDetails.getDate()));
			bean.setPhysicalCCIssuedOn(RESUtil.convertDateToString(ccDetails.getPhysicalCCIssuedOn()));
			bean.setFinancialCCIssuedOn(RESUtil.convertDateToString(ccDetails.getFinancialCCIssuedOn()));
			bean.setCcInspectionSubmittedOn(RESUtil.convertDateToString(ccDetails.getCcInspectionSubmittedOn()));
			if (ccDetails.getCreatedBy() != null) {
				bean.setCcInspectionInspectedBy(convertUserEntityToBean(userRepository
						.findByEmailIdAndStatusNot(ccDetails.getCreatedBy(), RESConstants.STATUS_DELETED)));
			}
		}

		if (entity.getIsEstimationRevised() != null) {
			bean.setIsEstimationRevised(entity.getIsEstimationRevised());
			bean.setCompetentAuthDesig(entity.getCompetentAuthDesig());
			bean.setCompetentAuthName(entity.getCompetentAuthName());
			bean.setRevisedLetterNo(entity.getRevisedLetterNo());
			if (entity.getLetterNoDate() != null)
				bean.setLetterNoDate(RESUtil.convertDateToString(entity.getLetterNoDate()));

		}
		// bean.setRevisedLetterNo(entity.getRevisedLetterNo());
		bean.setRevisedAsAmt(entity.getRevisedAsAmt());
		bean.setRevisedTsAmt(entity.getRevisedTsAmt());

		return bean;

	}

