	public List<WorkTemplateBean> fetchWorkTemplateItems(Long workTypeId, Long workSubTypeId) {
		try {

			WorkType workType = workTypeRepository.findOne(workTypeId);

			List<WorkTemplate> itemList = workTemplateRepository.findByWorkTypeAndParentItemAndEnabled(workType, null,
					true);

			List<WorkTemplateBean> workTemplateBeans = new ArrayList<>();
			if (itemList != null) {
				Integer counter = 1;

				for (WorkTemplate item : itemList) {

					WorkTemplateBean templateBean = new WorkTemplateBean();
					convertWorkTemplateEntityToBean(item, templateBean);
					workTemplateBeans.add(templateBean);
					if (item.getHasChild() || (!item.getHasChild() && item.getParentItem() == null)) {
						templateBean.setSerialNo(counter);
						counter++;
					}
					if (item.getHasChild()) {
						List<WorkTemplateBean> childBeans1 = new LinkedList<WorkTemplateBean>();
						for (WorkTemplate child : item.getChildItems()) {
							WorkTemplateBean templateBean1 = new WorkTemplateBean();
							convertWorkTemplateEntityToBean(child, templateBean1);
							childBeans1.add(templateBean1);
							templateBean.setChildItems(childBeans1);
							workTemplateBeans.add(templateBean1);
							if (child.getHasChild()) {
								for (WorkTemplate child2 : child.getChildItems()) {
									List<WorkTemplateBean> childBeans2 = new LinkedList<WorkTemplateBean>();
									WorkTemplateBean templateBean2 = new WorkTemplateBean();
									convertWorkTemplateEntityToBean(child2, templateBean2);
									childBeans2.add(templateBean2);
									templateBean1.setChildItems(childBeans2);
									workTemplateBeans.add(templateBean2);
								}
							}
						}

					}
				}
			}

			return workTemplateBeans;
		} catch (Exception e) {
			e.printStackTrace();
			logger.error("An exception occurred.", e);
			return null;
		}
	}

	@Override
	public List<WorkTemplateBean> fetchWorkTemplateItemsForEstimation(Long workTypeId, Long standardTemplateTypeId,
			Short templateType) {
		try {

			WorkType workType = workTypeRepository.findOne(workTypeId);
			// WorkSubType workSubType = workSubTypeRepository
			// .findOne(workSubTypeId);

			StandardTemplateType standardTemplateType = null;
			if (null != standardTemplateTypeId) {
				standardTemplateType = standardTemplateTypeRepository.findByIdAndEnabled(standardTemplateTypeId,
						(short) 1);
			}

			List<WorkTemplate> itemList = workTemplateRepository
					.findByWorkTypeAndStandardTemplateTypeAndTemplateTypeAndParentItemAndEnabled(workType,
							standardTemplateType, templateType, null, true);

			List<WorkTemplateBean> workTemplateBeans = new ArrayList<>();
			if (itemList != null) {
				Integer counter = 1;
				Integer index = 0;

				int lastItemCount = 0;
				for (WorkTemplate item : itemList) {

					WorkTemplateBean templateBean = new WorkTemplateBean();
					templateBean.setIndex(index);
					convertWorkTemplateEntityToBean(item, templateBean);
					workTemplateBeans.add(templateBean);
					index++;

					// settingLastItemFlag in WorkTemplateBean.
					if (itemList.size() == lastItemCount + 1) {
						templateBean.setLastElement(true);
					}
					lastItemCount++;
					// close here.

					int cululativeChildCount = 0;
					if (item.getHasChild()) {
						templateBean.setSerialNo(counter);
						counter++;
						List<WorkTemplateBean> workTemplateBeans2 = new LinkedList<WorkTemplateBean>();

						int lastItemCount1 = 0;
						for (WorkTemplate child : item.getChildItems()) {
							cululativeChildCount++;
							int cululativeChildCount1 = 0;
							WorkTemplateBean workTemplateBean1 = new WorkTemplateBean();

							workTemplateBean1.setIndex(index);
							workTemplateBean1.setParentId(templateBean.getId());
							workTemplateBean1.setParentIndex(templateBean.getIndex());
							if (null != templateBean.getGroup() && !templateBean.getGroup()) {
								workTemplateBean1.setLeafNode(true);
							}
							convertWorkTemplateEntityToBean(child, workTemplateBean1);
							workTemplateBeans2.add(workTemplateBean1);
							workTemplateBeans.add(workTemplateBean1);
							index++;

							// settingLastItemFlag in WorkTemplateBean.
							if (item.getChildItems().size() == lastItemCount1 + 1) {
								workTemplateBean1.setLastElement(true);
							}
							lastItemCount1++;
							// close here.

							templateBean.setChildItems(workTemplateBeans2);
							templateBean.setChildsCount(workTemplateBeans2.size());

							if (child.getHasChild()) {
								List<WorkTemplateBean> workTemplateBeans3 = new LinkedList<WorkTemplateBean>();

								int lastItemCount2 = 0;
								for (WorkTemplate child2 : child.getChildItems()) {
									cululativeChildCount++;
									cululativeChildCount1++;
									WorkTemplateBean workTemplateBean2 = new WorkTemplateBean();

									workTemplateBean2.setIndex(index);
									workTemplateBean2.setParentId(workTemplateBean1.getId());
									workTemplateBean2.setParentIndex(workTemplateBean1.getIndex());
									workTemplateBean2.setLeafNode(true);

									convertWorkTemplateEntityToBean(child2, workTemplateBean2);
									workTemplateBeans3.add(workTemplateBean2);
									workTemplateBeans.add(workTemplateBean2);
									workTemplateBean1.setChildItems(workTemplateBeans3);
									workTemplateBean1.setChildsCount(workTemplateBeans3.size());
									index++;

									// settingLastItemFlag in WorkTemplateBean.
									if (child.getChildItems().size() == lastItemCount2 + 1) {
										workTemplateBean2.setLastElement(true);
									}
									lastItemCount2++;
									// close here.
								}
							}
							workTemplateBean1.setCumulativeChildsCount(cululativeChildCount1);
						}
					} else if (item.getParentItem() == null) {
						templateBean.setSerialNo(counter);
						counter++;
					}
					templateBean.setCumulativeChildsCount(cululativeChildCount);
				}
			}

			return workTemplateBeans;
		} catch (Exception e) {
			e.printStackTrace();
			logger.error("An exception occurred.", e);
			return null;
		}
	}

