	private void populateWorkEstimationBeanFromEntity(WorkEstimation workEstimation,
			WorkEstimationBean workEstimationBean, boolean itemRequired) {

		// newly added as per Revision CR
		workEstimationBean.setCompetentAuthDesig(workEstimation.getCompetentAuthDesig());
		workEstimationBean.setCompetentAuthName(workEstimation.getCompetentAuthName());
		workEstimationBean.setRevisedLetterNo(workEstimation.getRevisedLetterNo());
		if (workEstimation.getLetterNoDate() != null)
			workEstimationBean.setLetterNoDate(RESUtil.convertDateToString(workEstimation.getLetterNoDate()));

		workEstimationBean.setEstimationId(workEstimation.getId());
		if (null != workEstimation.getTotalAmount()) {
			workEstimationBean.setEstimatedAmount(workEstimation.getTotalAmount().toString());
		}

		workEstimationBean.setEstimationType(workEstimation.getEstimationType());
		workEstimationBean.setExecutionAgency(workEstimation.getWork().getAgencyTypeId().getAgencyTypeNameE());
		workEstimationBean.setGrandTotal(workEstimation.getGrandTotal().toString());

		if (null != workEstimation.getStatus()) {
			workEstimationBean.setEstimationStatusId(workEstimation.getStatus().getId());
			workEstimationBean.setStatus(workEstimation.getStatus().getStatusNameE());
		}

		if (null != workEstimation.getTotalAmountExcavation()) {
			workEstimationBean.setTotalAmountExcavation(workEstimation.getTotalAmountExcavation().toString());
		}
		if (null != workEstimation.getTotalAmountLooseningOfSoil()) {
			workEstimationBean.setTotalAmountLooseningOfSoil(workEstimation.getTotalAmountLooseningOfSoil().toString());
		}
		if (null != workEstimation.getTotalAmountMachinery()) {
			workEstimationBean.setTotalAmountMachinery(workEstimation.getTotalAmountMachinery().toString());
		}
		if (null != workEstimation.getTotalAmountMaterial()) {
			workEstimationBean.setTotalAmountMaterial(workEstimation.getTotalAmountMaterial().toString());
		}
		if (null != workEstimation.getTotalAmountLabour()) {
			workEstimationBean.setTotalLabourComponent(workEstimation.getTotalAmountLabour().toString());
		}
		workEstimationBean.setWorkId(workEstimation.getWork().getId());
		workEstimationBean.setWorkName(workEstimation.getWork().getWorkName());
		if (null != workEstimation.getWork().getWorkSubTypeId()) {
			workEstimationBean.setWorkSubType(workEstimation.getWork().getWorkSubTypeId().getWorkSubTypeNameE());
		}
		workEstimationBean.setWorkType(workEstimation.getWork().getWorkTypeId().getWorkTypeNameE());
		if (null != workEstimation.getApplicableGstAmt()) {
			workEstimationBean.setApplicableGstAmt(workEstimation.getApplicableGstAmt().toString());
		}
		if (null != workEstimation.getApplicableGstPer()) {
			workEstimationBean
					.setApplicableGstPer(workEstimation.getApplicableGstPer().stripTrailingZeros().toPlainString());
		}
		if (null != workEstimation.getExpectedTenderedAmt()) {
			workEstimationBean.setExpectedTenderedAmt(workEstimation.getExpectedTenderedAmt().toPlainString());
		}
		if (null != workEstimation.getExpectedTenderedRatePer()) {
			workEstimationBean.setExpectedTenderedRatePer(
					workEstimation.getExpectedTenderedRatePer().stripTrailingZeros().toPlainString());
		}
		if (null != workEstimation.getLabourWelfareComponentPer()) {
			workEstimationBean.setLabourWelfareComponentPer(
					workEstimation.getLabourWelfareComponentPer().stripTrailingZeros().toPlainString());
		}
		if (null != workEstimation.getLabourWelfareComponentAmt()) {
			workEstimationBean
					.setLabourWelfareComponentAmt(workEstimation.getLabourWelfareComponentAmt().toPlainString());
		}
		if (null != workEstimation.getOverheadChargesAmt()) {
			workEstimationBean.setOverheadChargesAmt(workEstimation.getOverheadChargesAmt().toPlainString());
		}
		if (null != workEstimation.getOverheadChargesPer()) {
			workEstimationBean
					.setOverheadChargesPer(workEstimation.getOverheadChargesPer().stripTrailingZeros().toPlainString());
		}

		if (null != workEstimation.getWorkChargeContingencyPer()) {
			workEstimationBean.setWorkChargeContingencyPer(
					workEstimation.getWorkChargeContingencyPer().stripTrailingZeros().toPlainString());
		}
		if (null != workEstimation.getWorkChargeContingencyAmt()) {
			workEstimationBean
					.setWorkChargeContingencyAmt(workEstimation.getWorkChargeContingencyAmt().toPlainString());
		}

		if (null != workEstimation.getAdministrativeExpenditurePer()) {
			workEstimationBean.setAdministrativeExpenditurePer(
					workEstimation.getAdministrativeExpenditurePer().stripTrailingZeros().toPlainString());
		}
		if (null != workEstimation.getAdministrativeExpenditureAmt()) {
			workEstimationBean
					.setAdministrativeExpenditureAmt(workEstimation.getAdministrativeExpenditureAmt().toPlainString());
		}
		if (null != workEstimation.getOthersCharges()) {
			workEstimationBean.setOthersCharges(workEstimation.getOthersCharges().toPlainString());
		}

		if (null != workEstimation.getStatus() && workEstimation.getStatus().getId() != 1) {
			workEstimationBean.setCeComments(workEstimation.getCommentsCe());
			if (null != workEstimation.getCeFwdDate()) {
				workEstimationBean.setCeFwdDate(RESUtil.convertDateToStringWithFormat(workEstimation.getCeFwdDate(),
						RESConstants.DATE_FORMAT_HH_MM));
			}

			workEstimationBean.setSeComments(workEstimation.getCommentsSe());
			if (null != workEstimation.getSeFwdDate()) {
				workEstimationBean.setSeFwdDate(RESUtil.convertDateToStringWithFormat(workEstimation.getSeFwdDate(),
						RESConstants.DATE_FORMAT_HH_MM));
			}

			String userName = workEstimation.getEstimationApprovedBy();
			if (userName != null) {
				UserBean userbean = userService.fetchUserDetailsByUserName(userName);
				workEstimationBean.setApprovedByUser(userbean);
			}

			workEstimationBean.setEeComments(workEstimation.getCommentsEe());
			if (null != workEstimation.getEeFwdDate()) {
				workEstimationBean.setEeFwdDate(RESUtil.convertDateToStringWithFormat(workEstimation.getEeFwdDate(),
						RESConstants.DATE_FORMAT_HH_MM));
			}

			workEstimationBean.setAeComments(workEstimation.getCommentsAe());
			if (null != workEstimation.getAeFwdDate()) {
				workEstimationBean.setAeFwdDate(RESUtil.convertDateToStringWithFormat(workEstimation.getAeFwdDate(),
						RESConstants.DATE_FORMAT_HH_MM));
			}
			workEstimationBean.setSubEngComments(workEstimation.getCommentsSubEng());
			if (null != workEstimation.getSubEngFwdDate()) {
				workEstimationBean.setSubEngFwdDate(RESUtil.convertDateToStringWithFormat(
						workEstimation.getSubEngFwdDate(), RESConstants.DATE_FORMAT_HH_MM));
			}
			workEstimationBean.setSdoComments(workEstimation.getCommentsSdo());
			if (null != workEstimation.getSdoFwdDate()) {
				workEstimationBean.setSdoFwdDate(RESUtil.convertDateToStringWithFormat(workEstimation.getSdoFwdDate(),
						RESConstants.DATE_FORMAT_HH_MM));
			}
		}
		if (null != workEstimation.getCreatedDate()) {
			workEstimationBean.setEstimationSubmissionDate(RESUtil
					.convertDateToStringWithFormat(workEstimation.getCreatedDate(), RESConstants.DATE_FORMAT_HH_MM));
		}

		if (null != workEstimation.getStatus() && workEstimation.getStatus().getId() == 1) {
			if (null != workEstimation.getCommentsSubEng()) {
				workEstimationBean.setComments(workEstimation.getCommentsSubEng());
			}
			if (null != workEstimation.getCommentsSdo()) {
				workEstimationBean.setComments(workEstimation.getCommentsSdo());
			} else if (null != workEstimation.getCommentsAe()) {
				workEstimationBean.setComments(workEstimation.getCommentsAe());
			} else if (null != workEstimation.getCommentsEe()) {
				workEstimationBean.setComments(workEstimation.getCommentsEe());
			}
		}
		if (itemRequired) {
			List<WorkEstimationItems> workEstimationItems = workEstimationItemsRepository
					.findByWorkEstimationAndEnabled(workEstimation, true);
			if (null != workEstimationItems) {
				List<WorkTemplateBean> workTemplateItems = new LinkedList<WorkTemplateBean>();
				for (WorkEstimationItems workEstimationItem : workEstimationItems) {
					WorkTemplateBean workTemplateBean = new WorkTemplateBean();
					populateWorkTemplateBeanFromEntity(workEstimationItem, workTemplateBean);
					workTemplateItems.add(workTemplateBean);
				}
				workEstimationBean.setWorkTemplateItems(workTemplateItems);
			}
		}

		if (workEstimation.getHasNonSorItems() != null) {
			workEstimationBean.setHasNonSorItems(workEstimation.getHasNonSorItems());
		}

		if (workEstimation.getTenPercentCheck() != null) {
			workEstimationBean.setTenPercentCheck(workEstimation.getTenPercentCheck());
		}
	}

	private void populateWorkTemplateBeanFromEntity(WorkEstimationItems workEstimationItem,
			WorkTemplateBean workTemplateBean) {
		workTemplateBean.setId(workEstimationItem.getId());
		if (null != workEstimationItem.getAmoountMachinery()) {
			workTemplateBean.setAmoountMachinery(workEstimationItem.getAmoountMachinery().toString());
		}
		if (null != workEstimationItem.getAmount()) {
			workTemplateBean.setAmount(workEstimationItem.getAmount().toString());
		}
		if (null != workEstimationItem.getAmountExcavation()) {
			workTemplateBean.setAmountExcavation(workEstimationItem.getAmountExcavation().toString());
		}
		if (null != workEstimationItem.getAmountLooseningSoil()) {
			workTemplateBean.setAmountLooseningSoil(workEstimationItem.getAmountLooseningSoil().toString());
		}
		if (null != workEstimationItem.getAmountMaterial()) {
			workTemplateBean.setAmountMaterial(workEstimationItem.getAmountMaterial().toString());
		}

		if (null != workEstimationItem.getHeightDepth()) {
			workTemplateBean.setMeasureHeightDepth(true);
			workTemplateBean.setHeightDepth(workEstimationItem.getHeightDepth().stripTrailingZeros().toPlainString());
		}
		if (null != workEstimationItem.getWidth()) {
			workTemplateBean.setMeasureWidth(true);
			workTemplateBean.setWidth(workEstimationItem.getWidth().stripTrailingZeros().toPlainString());
		}
		if (null != workEstimationItem.getLength()) {
			workTemplateBean.setMeasureLength(true);
			workTemplateBean.setLength(workEstimationItem.getLength().stripTrailingZeros().toPlainString());
		}
		workTemplateBean.setId(workEstimationItem.getId());
		workTemplateBean.setItemDesc(workEstimationItem.getItemDesc());
		if (null != workEstimationItem.getAmountLabour()) {
			workTemplateBean.setLabourComponentValue(workEstimationItem.getAmountLabour().toString());
			workTemplateBean.setLabourComponent(true);
		}
		if (null != workEstimationItem.getNo()) {
			workTemplateBean.setNo(workEstimationItem.getNo().stripTrailingZeros().toPlainString());
		}
		if (null != workEstimationItem.getQuantity()) {
			workTemplateBean.setQuantity(workEstimationItem.getQuantity().stripTrailingZeros().toPlainString());
		}
		if (null != workEstimationItem.getRate()) {
			workTemplateBean.setRate(workEstimationItem.getRate().stripTrailingZeros().toPlainString());
		}
		if (null != workEstimationItem.getRateLabour()) {
			workTemplateBean.setRateLabour(workEstimationItem.getRateLabour().stripTrailingZeros().toPlainString());
		}
		workTemplateBean.setSorItemNo(workEstimationItem.getSorItemNo());
		workTemplateBean.setUnit(workEstimationItem.getUnit());
		workTemplateBean.setHasChild(workEstimationItem.getHasChild());
		if (null != workEstimationItem.getHasChild() && workEstimationItem.getHasChild()) {
			workTemplateBean.setParentItem(new WorkTemplateBean());
		}

		if (null != workEstimationItem.getUnit() && !workEstimationItem.getUnit().isEmpty()) {
			workTemplateBean.setUnitReadOnly(true);
		}
		if (null != workEstimationItem.getRate()) {
			workTemplateBean.setRateReadOnly(true);
		}
		if (null != workEstimationItem.getSorItemNo() && !workEstimationItem.getSorItemNo().isEmpty()) {
			workTemplateBean.setSorItemNoReadOnly(true);
		}
		if (null != workEstimationItem.getItemDesc() && !workEstimationItem.getItemDesc().isEmpty()) {
			workTemplateBean.setDescReadOnly(true);
		}
		workTemplateBean.setGroup(workEstimationItem.getGroup());
		workTemplateBean.setNew(false);
	}

	private void convertWorkTemplateEntityToBean(WorkTemplate item, WorkTemplateBean templateBean) {

		templateBean.setId(item.getId());
		if (item.getWorkType() != null)
			templateBean.setWorkTypeId(item.getWorkType().getWorkTypeId());
		if (item.getStandardTemplateType() != null) {
			templateBean.setStandardTemplateTypeId(item.getStandardTemplateType().getId());
		}

		templateBean.setSorItemNo(item.getSorItemNo());
		templateBean.setSorType(item.getSorType());
		templateBean.setItemDesc(item.getItemDesc());
		templateBean.setMeasureLength(item.getMeasureLength());
		templateBean.setMeasureWidth(item.getMeasureWidth());
		templateBean.setMeasureHeightDepth(item.getMeasureHeightDepth());
		templateBean.setUnit(item.getUnit());
		templateBean.setLabourComponent(item.getLabourComponent());
		templateBean.setSequenceNo(item.getSequenceNo());
		templateBean.setHasChild(item.getHasChild());

		templateBean.setEnabled(item.getEnabled());
		templateBean.setGroup(item.getGroup());
		templateBean.setRate(item.getRate());

		if (null != item.getNo()) {
			templateBean.setNo(item.getNo().toString());
		}
		if (null != item.getLength()) {
			templateBean.setLength(item.getLength().toString());
		}
		if (null != item.getWidth()) {
			templateBean.setWidth(item.getWidth().toString());
		}
		if (null != item.getHeightDepth()) {
			templateBean.setHeightDepth(item.getHeightDepth().toString());
		}
		if (null != item.getQuantity()) {
			templateBean.setQuantity(item.getQuantity().toString());
		}
		templateBean.setTemplateType(item.getTemplateType());

		if (item.getRate() != null) {
			templateBean.setReadOnly(true);
		} else {
			templateBean.setReadOnly(false);
		}

		if (item.getParentItem() != null) {
			WorkTemplateBean parent = new WorkTemplateBean();
			parent.setId(item.getParentItem().getId());
			parent.setSorItemNo(item.getParentItem().getSorItemNo());
			templateBean.setParentItem(parent);
		}
		if (null != item.getUnit() && !item.getUnit().isEmpty()) {
			templateBean.setUnitReadOnly(true);
		}
		if (null != item.getRate() && !item.getRate().isEmpty()) {
			templateBean.setRateReadOnly(true);
		}
		if (null != item.getSorItemNo() && !item.getSorItemNo().isEmpty()) {
			templateBean.setSorItemNoReadOnly(true);
		}
		if (null != item.getItemDesc() && !item.getItemDesc().isEmpty()) {
			templateBean.setDescReadOnly(true);
		}
		templateBean.setNew(false);

		if (null != item.getRate() && !item.getRate().isEmpty() && null != item.getQuantity()) {
			BigDecimal bd1 = new BigDecimal(item.getRate());
			BigDecimal bd2 = bd1.multiply(item.getQuantity());
			templateBean.setAmount(bd2.setScale(2, BigDecimal.ROUND_HALF_UP).toString());
		}
	}

	@Override
	public BillBean fetchPrevBillDetailsByBillId(Long billId) {
		try {
			BillBean billBean = null;

			Bill bill = billRepository.findOne(billId);

			int index = bill.getBillIndex();

			Work work = workRepository.findOne(bill.getWork().getId());

			/*
			 * List<Bill> bills =
			 * billRepository.findByWorkAndToShowAndStatusStatusIdNotIn(work, true,
			 * RESConstants.STATUS_FINAL_BILL_REJECTED_ID);
			 */

			List<Bill> bills = billRepository.findByWorkAndToShowAndStatusStatusIdNotInAndStatusStatusIdNotIn(work,
					true, RESConstants.STATUS_FINAL_BILL_REJECTED_ID, RESConstants.STATUS_DELETED_ID);

			// List<Bill> bills = billRepository.findByWorkAndStatusStatusIdNotIn(work,
			// RESConstants.STATUS_FINAL_BILL_REJECTED_ID);

			if (bills != null && !bills.isEmpty()) {

				BigDecimal amountSum = bills.stream().filter(bill1 -> bill1.getBillIndex() != index).collect(
						Collectors.reducing(BigDecimal.ZERO, Bill::getBillAmountWithoutDeduction, BigDecimal::add));

				BigDecimal gstForRemaining = bills.stream().filter(bill1 -> bill1.getBillIndex() != index)
						.collect(Collectors.reducing(BigDecimal.ZERO, Bill::getGst, BigDecimal::add));

				BigDecimal addOthersForRemaining = bills.stream().filter(bill1 -> bill1.getBillIndex() != index)
						.collect(Collectors.reducing(BigDecimal.ZERO, Bill::getAddOthers, BigDecimal::add));

				BigDecimal totalAmountPreviousBillsWOgstWOaddOthers = amountSum
						.subtract((gstForRemaining.add(addOthersForRemaining)));

				List<Bill> prevBillList = bills.stream().filter(bill1 -> {
					return bill1.getBillIndex() == (index - 1);
				}).collect(Collectors.toList());

				if (prevBillList != null && !prevBillList.isEmpty()) {

					Bill prevBill = prevBillList.get(0);

					billBean = convertBillEntityToBean(prevBill);

					billBean.setTotalAmountPreviousBills(amountSum);

					// setting BillAmountWithoutGstAndDeductions
					BigDecimal gstAndAddOthers = gstForRemaining.add(addOthersForRemaining);
					BigDecimal billAmountWithoutGstAndDeductions = amountSum.subtract(gstAndAddOthers);
					billBean.setBillAmountWithoutGstAndDeductions(billAmountWithoutGstAndDeductions);

					billBean.setTotalAmountPreviousBillsWOgstWOaddOthers(totalAmountPreviousBillsWOgstWOaddOthers);

					List<BillItems> billItems = billItemsRepository.findByBill(prevBill);
					if (billItems != null && !billItems.isEmpty()) {

						List<BillItemBean> billItemBeanList = new ArrayList<>();
						for (BillItems item : billItems) {
							billItemBeanList.add(convertBillItemsEntityToBean(item));
						}
						billBean.setBillItems(billItemBeanList);
					}
				}

			}
			List<TechnicalSanction> revisedTsList = technicalSanctionRepository
					.findByWorkAndTechnicalStatusAndTechnicalSanctionTypeOrderByModifiedDateDesc(work,
							new TechnicalStatus(RESConstants.TS_STATUS_DISPATCHED),
							new TechnicalSanctionType(RESConstants.TS_TYPE_STATUS_REVISED));

			// latest received TS
			AdministrationSanction latestAs = administrationSanctionRepository
					.findByWorkAndAdministrativeStatusOrderByCreatedDateDesc(work,
							new AdministrativeStatus(RESConstants.AS_RECEIVED))
					.size() > 0
							? administrationSanctionRepository.findByWorkAndAdministrativeStatusOrderByCreatedDateDesc(
									work, new AdministrativeStatus(RESConstants.AS_RECEIVED)).get(0)
							: null;

			if (null != latestAs && null != billBean)
				billBean.setFinalAsBillingAmount(latestAs.getAdministrativeSanctionAmount());

			if (null != revisedTsList && !revisedTsList.isEmpty()) {
				for (TechnicalSanction revisedTs : revisedTsList) {
					// if(null != latestAs) {
					if (null != latestAs && revisedTs.getTechnicalSanctionAmount()
							.compareTo(latestAs.getAdministrativeSanctionAmount()) <= 0) {
						if (null != billBean)
							billBean.setEstimationRevised(true);
						break;
					} else {
						AdministrationSanction as = administrationSanctionRepository
								.findByTechnicalSanctionId(new TechnicalSanction(revisedTs.getId()));
						if (null != as && RESConstants.AS_RECEIVED.equals(as.getAdministrativeStatus().getId())) {
							if (null != billBean)
								billBean.setEstimationRevised(true);
							break;
						}
					}
					// }
				}
			}
			if (null != work.getRevisedAsAmt() && work.getRevisedAsAmt().compareTo(BigDecimal.ZERO) == 1) {
				billBean.setFinalAsBillingAmount(work.getRevisedAsAmt());
				billBean.setEstimationRevised(true);
			}

			return billBean;
		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return null;
		}
	}

	@Override
	public BillBean fetchLastBillDetails(Long workId) {
		try {
			BillBean billBean = null;
			Work work = workRepository.findOne(workId);

//			List<Bill> bills = billRepository.findByWorkAndToShow(work, true);

			/*
			 * List<Bill> bills =
			 * billRepository.findByWorkAndToShowAndStatusStatusIdNotIn(work, true,
			 * RESConstants.STATUS_FINAL_BILL_REJECTED_ID);
			 */
			List<Bill> bills = billRepository.findByWorkAndToShowAndStatusStatusIdNotInAndStatusStatusIdNotIn(work,
					true, RESConstants.STATUS_FINAL_BILL_REJECTED_ID, RESConstants.STATUS_DELETED_ID);

			if (bills != null && !bills.isEmpty()) {

				BigDecimal amountSum = bills.stream().collect(
						Collectors.reducing(BigDecimal.ZERO, Bill::getBillAmountWithoutDeduction, BigDecimal::add));

				BigDecimal gstForRemaining = bills.stream()
						.collect(Collectors.reducing(BigDecimal.ZERO, Bill::getGst, BigDecimal::add));

				BigDecimal addOthersForRemaining = bills.stream()
						.collect(Collectors.reducing(BigDecimal.ZERO, Bill::getAddOthers, BigDecimal::add));

				Optional<Bill> latestBillOfWork = bills.stream()
						.collect(Collectors.maxBy(Comparator.comparing(Bill::getBillIndex)));
				Bill latestBill = latestBillOfWork.isPresent() ? latestBillOfWork.get() : null;

				billBean = convertBillEntityToBean(latestBill);
				billBean.setTotalAmountPreviousBills(amountSum);

				// setting BillAmountWithoutGstAndDeductions
				BigDecimal gstAndAddOthers = gstForRemaining.add(addOthersForRemaining);
				BigDecimal billAmountWithoutGstAndDeductions = amountSum.subtract(gstAndAddOthers);
				billBean.setBillAmountWithoutGstAndDeductions(billAmountWithoutGstAndDeductions);

				if (latestBill != null) {

					List<BillItems> billItems = billItemsRepository.findByBill(latestBill);
					if (billItems != null && !billItems.isEmpty()) {

						List<BillItemBean> billItemBeanList = new ArrayList<>();
						for (BillItems item : billItems) {
							billItemBeanList.add(convertBillItemsEntityToBean(item));
						}
						billBean.setBillItems(billItemBeanList);
					}
				}
			}

			// revised Estimation
			/*
			 * List<WorkEstimation> revisedEstimationList=workEstimationRepository.
			 * findByWorkAndStatusAndEstimationTypeOrderByModifiedDateDesc(work, new
			 * WorkEstimationStatus(RESConstants.ESTIMATION_STATUS_APPROVED),
			 * RESConstants.ESTIMATION_REVISED);
			 */

			List<TechnicalSanction> revisedTsList = technicalSanctionRepository
					.findByWorkAndTechnicalStatusAndTechnicalSanctionTypeOrderByModifiedDateDesc(work,
							new TechnicalStatus(RESConstants.TS_STATUS_DISPATCHED),
							new TechnicalSanctionType(RESConstants.TS_TYPE_STATUS_REVISED));

			// latest received TS
			AdministrationSanction latestAs = administrationSanctionRepository
					.findByWorkAndAdministrativeStatusOrderByCreatedDateDesc(work,
							new AdministrativeStatus(RESConstants.AS_RECEIVED))
					.size() > 0
							? administrationSanctionRepository.findByWorkAndAdministrativeStatusOrderByCreatedDateDesc(
									work, new AdministrativeStatus(RESConstants.AS_RECEIVED)).get(0)
							: null;

			if (null != latestAs && null != billBean)
				billBean.setFinalAsBillingAmount(latestAs.getAdministrativeSanctionAmount());

			if (null != revisedTsList && !revisedTsList.isEmpty()) {
				for (TechnicalSanction revisedTs : revisedTsList) {
					// if(null!=latestAs) {
					if (null != latestAs && revisedTs.getTechnicalSanctionAmount()
							.compareTo(latestAs.getAdministrativeSanctionAmount()) <= 0) {
						billBean.setEstimationRevised(true);
						break;
					} else {
						AdministrationSanction as = administrationSanctionRepository
								.findByTechnicalSanctionId(new TechnicalSanction(revisedTs.getId()));
						if (null != as && RESConstants.AS_RECEIVED.equals(as.getAdministrativeStatus().getId())) {
							billBean.setEstimationRevised(true);
							break;
						}
					}
					// }
				}
			}
			if (null != work.getRevisedAsAmt() && work.getRevisedAsAmt().compareTo(BigDecimal.ZERO) == 1) {
				billBean.setFinalAsBillingAmount(work.getRevisedAsAmt());
				billBean.setEstimationRevised(true);
			}
			return billBean;
		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return null;
		}
	}

	@Override
	public String fetchDownloadFileName(Long documentId) {

		DocumentUpload document = documentRepository.findOne(documentId);
		String fileName = document.getDocumentName();
		String compareString = fileName.split("_")[0];
		String fileWithFullPath = null;
		switch (compareString) {
		case "agreement":
			fileWithFullPath = documentRootPath + workDocumentPath + fileName;
			break;

		case "admin":
			fileWithFullPath = documentRootPath + workAdminSanctionDocumentPath + fileName;
			break;

		case "drawing":
			fileWithFullPath = documentRootPath + workTechSanctionDocumentPath + fileName;
			break;

		case "estimation":
			fileWithFullPath = documentRootPath + workTechSanctionDocumentPath + fileName;
			break;

		case "technical":
			fileWithFullPath = documentRootPath + workTechSanctionDocumentPath + fileName;
			break;

		case "requisition":
			fileWithFullPath = documentRootPath + workRequisitionPath + fileName;
			break;

		case "inspection":
			fileWithFullPath = documentRootPath + inspectionPath + fileName;
			break;

		case "inspectionCC":
			fileWithFullPath = documentRootPath + inspectionPathCC + fileName;
			break;

		case "physicalCC":
			fileWithFullPath = documentRootPath + ccFilePath + fileName;
			break;

		case "financialCC":
			fileWithFullPath = documentRootPath + ccFilePath + fileName;
			break;

		case "sqm":
			String fileOrImage = fileName.split("_")[2];
			/* String fileOrImage = fileName; */
			if (null != fileOrImage && fileOrImage.equalsIgnoreCase("file")) {
				fileWithFullPath = documentRootPath + inspectionPathSqmFile + fileName;
			} else if (null != fileOrImage && fileOrImage.equalsIgnoreCase("image")) {
				fileWithFullPath = documentRootPath + inspectionPathSqmImage + fileName;
			}
			break;
		// for Officer Unspection Download Image And File By Nikhil Jain
		case "officer":
			String fileOrImageOfficer = fileName.split("_")[2];
			/* String fileOrImage = fileName; */
			if (null != fileOrImageOfficer && fileOrImageOfficer.equalsIgnoreCase("file")) {
				fileWithFullPath = documentRootPath + inspectionPathOfficerFile + fileName;
			} else if (null != fileOrImageOfficer && fileOrImageOfficer.equalsIgnoreCase("image")) {
				fileWithFullPath = documentRootPath + inspectionPathOfficerImage + fileName;

			}
			break;
		case "kml":
			fileWithFullPath = documentRootPath + workMasterKmlFilePath + fileName;
			break;

		default:
			break;
		}
		System.out.println(fileWithFullPath);
		return fileWithFullPath;
	}

