	@Override
	public WorkJson getAllWorksByNameP(Pageable pageable, String searchBoxVal, String loggedInUserRole,
			String username) {
		WorkJson billJson = null;
		Page<Work> works = null;
		List<WorkBean> beanList = new ArrayList<>();
		try {

			Users entity = userRepository.findByUsernameAndStatus(username, RESConstants.STATUS_ACTIVE);

			long count = 0;

			if (searchBoxVal.equals("")) {
				searchBoxVal = null;
			}

			final String search = searchBoxVal;

			if (search != null) {
				if (loggedInUserRole.equals(RESConstants.ROLE_EE)) {// EE login
					works = workRepository.fetchWorkListforEEByWorkName(pageable, entity.getOffice(), search);
					count = works.getTotalElements();
				} else if (loggedInUserRole.equals(RESConstants.ROLE_AE)) {// AE login
					works = workRepository.findByAssistantEngineerByWorkName(pageable, entity, search);
					count = works.getTotalElements();
				} else if (loggedInUserRole.equals(RESConstants.ROLE_SUB_ENGG)) {// SubE login
					works = workRepository.findBySubEngineerByWorkName(pageable, entity, search);
				} else if (loggedInUserRole.equals(RESConstants.ROLE_SDO)) {// SubE login
					works = workRepository.findBySubEngineerByWorkName(pageable, entity, search);
				} else if (loggedInUserRole.equals(RESConstants.ROLE_SUPDT_ENGG)) {// SUPDTE login{
					works = workRepository.findBySuperintendingEngineerOffice(pageable, entity.getOffice());
				} else if (loggedInUserRole.equals(RESConstants.ROLE_CE)) {// CE login{
					works = workRepository.findByChiefEngineerOffice(pageable, entity.getOffice());

				} else if (loggedInUserRole.equals(RESConstants.ROLE_CONTRACTOR)) {// AE login
					works = workRepository.findByContractorByWorkName(pageable, entity.getContractor(), search);
					count = works.getTotalElements();

				} else {
					works = workRepository.findByWorkNameContaining(pageable, searchBoxVal);
				}
			}

			else {

				if (loggedInUserRole.equals(RESConstants.ROLE_EE)) {// EE login
					works = workRepository.fetchWorkListforEE(pageable, entity.getOffice());
					count = works.getTotalElements();
				} else if (loggedInUserRole.equals(RESConstants.ROLE_AE)) {// AE login
					works = workRepository.findByAssistantEngineer(pageable, entity);
					count = works.getTotalElements();
				} else if (loggedInUserRole.equals(RESConstants.ROLE_SUB_ENGG)) {// SubE login
					works = workRepository.findBySubEngineer(pageable, entity);
				} else if (loggedInUserRole.equals(RESConstants.ROLE_SDO)) {// SubE login
					works = workRepository.findBySubEngineer(pageable, entity);
				} else if (loggedInUserRole.equals(RESConstants.ROLE_SUPDT_ENGG)) {// SUPDTE login{
					works = workRepository.findBySuperintendingEngineerOffice(pageable, entity.getOffice());
				} else if (loggedInUserRole.equals(RESConstants.ROLE_CE)) {// CE login{
					works = workRepository.findByChiefEngineerOffice(pageable, entity.getOffice());
				} else if (loggedInUserRole.equals(RESConstants.ROLE_CONTRACTOR)) {// AE login
					works = workRepository.findByContractor(pageable, entity.getContractor());
					count = works.getTotalElements();
				} else {
					works = workRepository.findByWorkNameContaining(pageable, searchBoxVal);
				}
			}

			/* if (works != null && !works.isEmpty()) { */
			if (works != null) {

				List<?> entityList = works.getContent();

				int index = 0;
				if (entityList != null && !entityList.isEmpty()) {
					if (entityList.get(0) instanceof Work) {
						for (Work work : works) {

							WorkBean bean = convertWorkEntityToBean(work);

							List<Bill> filterredList = billRepository.findByWorkAndBillTypeAndStatusStatusIdNotIn(work,
									"Final", Arrays.asList(RESConstants.STATUS_FINAL_BILL_REJECTED_ID,
											RESConstants.STATUS_DELETED_ID));

							if (filterredList != null) {

								if (filterredList.size() >= 1) {
									bean.setAddNewBillShow(false);
								} else {
									bean.setAddNewBillShow(true);
								}
							} else {
								bean.setAddNewBillShow(true);
							}

							bean.setIndex(++index);
							beanList.add(bean);
						}
					} else {
						for (Object objArr : entityList) {
							Object[] objArr1 = (Object[]) objArr;
							Work work = (Work) objArr1[0];
							WorkBean bean = convertWorkEntityToBean(work);

							List<Bill> filterredList = billRepository.findByWorkAndBillTypeAndStatusStatusIdNotIn(work,
									"Final", Arrays.asList(RESConstants.STATUS_FINAL_BILL_REJECTED_ID,
											RESConstants.STATUS_DELETED_ID));

							if (filterredList != null) {

								if (filterredList.size() >= 1) {
									bean.setAddNewBillShow(false);
								} else {
									bean.setAddNewBillShow(true);
								}
							} else {
								bean.setAddNewBillShow(true);
							}

							bean.setIndex(++index);
							beanList.add(bean);
						}
					}
				}

				billJson = new WorkJson();
				billJson.setiTotalDisplayRecords(works.getTotalElements());
				if (loggedInUserRole.equals(RESConstants.ROLE_EE)) {
					billJson.setiTotalRecords(workRepository.countWorkListforEE(entity.getOffice()));
				}
				if (loggedInUserRole.equals(RESConstants.ROLE_SDO)) {
					billJson.setiTotalRecords(workRepository.countBySubDivisionalOfficer(entity));
				}

				if (loggedInUserRole.equals(RESConstants.ROLE_CONTRACTOR)) {
					billJson.setiTotalRecords(workRepository.countByContractor(entity.getContractor()));
				}

				if (loggedInUserRole.equals(RESConstants.ROLE_SUB_ENGG)) {
					billJson.setiTotalRecords(workRepository.countBySubEngineer(entity));
				}

				billJson.setAaData(beanList);
			}

			return billJson;
		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return billJson;
		}
	}

