	@Override
	public List<BillBean> fetchInspectionBillsByWork(Long workId) {

		List<BillBean> billBeanList = new ArrayList<BillBean>();

		List<Bill> billList = billRepository.findByWork(new Work(workId));
		if (billList != null && !billList.isEmpty()) {
			for (Bill bill : billList) {
				BillBean billBean = convertBillEntityToBean(bill);
				billBeanList.add(billBean);
			}
		}

		return billBeanList;
	}

	@Override
	public BillJson fetchInspectionBills(Pageable pageable, String searchBoxVal, String billDateFrom, String billDateTo,
			String status, String loggedInUserRole, String username) {

		BillJson billJson = null;

		if (searchBoxVal.isEmpty())
			searchBoxVal = null;
		if (status.isEmpty())
			status = null;
		try {
			Date billDateFromDate = null;
			Date billDateToDate = null;
			if ((!StringUtils.isEmpty(billDateFrom) && !StringUtils.isEmpty(billDateTo))) {
				billDateFromDate = RESUtil.convertStringToDate(billDateFrom);
				billDateToDate = RESUtil.convertStringToDate(billDateTo);
			}
			Page<Bill> bill = null;

			Users users = userRepository.findByUsernameAndStatus(username, RESConstants.STATUS_ACTIVE);
			long count = 0;

			if (searchBoxVal != null || !StringUtils.isEmpty(status) || billDateFromDate != null
					|| billDateToDate != null) {
				if (loggedInUserRole.equals(RESConstants.ROLE_EE)) {
					bill = billRepository.findInspectionBillsByExecutiveEngineerOfficeForEE(pageable, users,
							searchBoxVal, billDateFromDate, billDateToDate,
							(status == null ? null : Long.valueOf(status)), users.getOffice());
					count = bill.getTotalElements();

				} else if (loggedInUserRole.equals(RESConstants.ROLE_AE)) {// AE login

					bill = billRepository.findInspectionBillsAEWithFilter(pageable, users, searchBoxVal,
							billDateFromDate, billDateToDate, (status == null ? null : Long.valueOf(status)));
					count = bill.getTotalElements();

				} else if (loggedInUserRole.equals(RESConstants.ROLE_SUB_ENGG)) {// SubE login

					bill = billRepository.findInspectionBillsSubEWithFilter(pageable, users, searchBoxVal,
							billDateFromDate, billDateToDate, (status == null ? null : Long.valueOf(status)));
					count = bill.getTotalElements();
				} else if (loggedInUserRole.equals(RESConstants.ROLE_SDO)) {// SubE login

					bill = billRepository.findInspectionBillsSubEWithFilter(pageable, users, searchBoxVal,
							billDateFromDate, billDateToDate, (status == null ? null : Long.valueOf(status)));
					count = bill.getTotalElements();
				}

			} else {
				if (loggedInUserRole.equals(RESConstants.ROLE_EE)) {// EE login

					bill = billRepository.findInspectionBillsEE(pageable, users, users.getOffice());
					count = bill.getTotalElements();

				} else if (loggedInUserRole.equals(RESConstants.ROLE_AE)) {// AE login

					bill = billRepository.findInspectionBillsAE(pageable, users);
					count = bill.getTotalElements();

				} else if (loggedInUserRole.equals(RESConstants.ROLE_SUB_ENGG)) {// SubE login

					bill = billRepository.findInspectionBillsSubEng(pageable, users);
					count = bill.getTotalElements();
				} else if (loggedInUserRole.equals(RESConstants.ROLE_SDO)) {// SubE login

					bill = billRepository.findInspectionBillsSDO(pageable, users);
					count = bill.getTotalElements();
				}
			}

			if (bill != null) {
				List<Bill> entityList = bill.getContent();
				List<BillBean> beanList = new ArrayList<>();
				if (entityList != null && !entityList.isEmpty()) {

					int index = pageable.getPageNumber() * pageable.getPageSize();
					for (Bill element : entityList) {

						BillBean bean = convertBillEntityToBean(element);
						bean.setIndex(++index);
						beanList.add(bean);
					}
				}
				billJson = new BillJson();
				billJson.setiTotalDisplayRecords(bill.getTotalElements());
				if (loggedInUserRole.equals(RESConstants.ROLE_EE)) {// EE login
					billJson.setiTotalRecords(billRepository.countInspectionBillsEE(users, users.getOffice()));
				}
				if (loggedInUserRole.equals(RESConstants.ROLE_AE)) {// AE login
					billJson.setiTotalRecords(billRepository.countInspectionBillsAE(users));
				}
				if (loggedInUserRole.equals(RESConstants.ROLE_SUB_ENGG)) {// SubE login
					billJson.setiTotalRecords(billRepository.countInspectionBillsSubEng(users));
				}
				if (loggedInUserRole.equals(RESConstants.ROLE_SDO)) {// SubE login
					billJson.setiTotalRecords(billRepository.countInspectionBillsSDO(users));
				}

				billJson.setAaData(beanList);
			}
			return billJson;
		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return billJson;
		}
	}

