	@Override
	public WorkDistrictJson getAllStatusWiseWorks(String role, UserBean userBean) {
		WorkDistrictJson workJson = null;
		try {
			List<DashboardBean> beanList = null;
			List<Object[]> objList = null;
			if (role.equals(RESConstants.ROLE_ADMIN) || role.equals(RESConstants.ROLE_EnC)) {
				objList = workRepository.findStatusWiseWorkListforAdminAndEnC();

			} else if (role.equals(RESConstants.ROLE_CE)) {
				objList = workRepository.findStatusWiseWorkListforCE(userBean.getOfficeId());
			} else if (role.equals(RESConstants.ROLE_SUPDT_ENGG)) {
				objList = workRepository.findStatusWiseWorkListforSE(userBean.getOfficeId());
			} else if (role.equals(RESConstants.ROLE_EE)) {
				objList = workRepository.findStatusWiseWorkListforEE(userBean.getOfficeId());
			} else if (role.equals(RESConstants.ROLE_AE)) {
				objList = workRepository.findStatusWiseWorkListforAE(userBean.getId());
			} else if (role.equals(RESConstants.ROLE_SUB_ENGG)) {
				objList = workRepository.findStatusWiseWorkListforSubEngineer(userBean.getId());
			} else if (role.equals(RESConstants.ROLE_SDO)) {
				objList = workRepository.findStatusWiseWorkListforSubEngineer(userBean.getId());
			}

			Integer count = 0;
			if (null != objList) {
				beanList = new LinkedList<DashboardBean>();
				Integer counter = 1;

				for (Object[] obj : objList) {
					DashboardBean dashboardBean = new DashboardBean();
					dashboardBean.setNumbering(counter);
					populateDashboardBeanFromObject(obj, dashboardBean);
					count = count + dashboardBean.getCount1();
					beanList.add(dashboardBean);
					counter++;
				}

			}

			workJson = new WorkDistrictJson();
			workJson.setiTotalRecords(count);

			workJson.setAaData(beanList);

			return workJson;
		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return workJson;
		}
	}

	private void populateDashboardBeanFromObject(Object[] obj, DashboardBean dashboardBean) {
		Long longVal = (Long) obj[0];
		dashboardBean.setId(longVal.intValue());
		dashboardBean.setName((String) obj[1]);
		Long longVal2 = (Long) obj[2];
		dashboardBean.setCount1(longVal2.intValue());
	}

