	private SqmAllocationBean convertInspectionDetailsEntityToSqmAllocationBeanDuringListing(
			InspectionDetails inspectionDetails) {
		SqmAllocationBean sqmAllocationBean = new SqmAllocationBean();
		sqmAllocationBean.setId(inspectionDetails.getId());

		Work work = workRepository.findOne(inspectionDetails.getWorkId());
		sqmAllocationBean.setWorkName(work.getWorkName());
		Users users = userRepository.findByUsernameAndStatus(inspectionDetails.getInspectedBy(),
				RESConstants.STATUS_ACTIVE);
		sqmAllocationBean.setOfficeId(users.getOffice().getId());
		Office office = officeRepository.findById(users.getOffice().getId());
		sqmAllocationBean.setOfficeName(office.getOfficeName());
		sqmAllocationBean.setInspectedBy(users.getName());
		sqmAllocationBean.setCreatedDate(RESUtil.convertDateToString(inspectionDetails.getCreatedOn()));
		sqmAllocationBean.setWorkRequisitionNo(work.getWorkRequisitionNo());

		return sqmAllocationBean;
	}

