	private SqmAllocationBean convertSqmAllocationEntityToBeanDuringListing(SqmAllocation sqmAllocation) {
		SqmAllocationBean sqmAllocationBean = new SqmAllocationBean();
		sqmAllocationBean.setId(sqmAllocation.getId());
		sqmAllocationBean.setWorkName(sqmAllocation.getWork().getWorkName());
		sqmAllocationBean.setOfficeId(sqmAllocation.getOfficeId());
		Office office = officeRepository.findById(sqmAllocation.getOfficeId());

		sqmAllocationBean.setOfficeName(office.getOfficeName());

		sqmAllocationBean.setInspectedBy(sqmAllocation.getUsers().getName());

		sqmAllocationBean.setCreatedDate(RESUtil.convertDateToString(sqmAllocation.getModifiedDate()));

		sqmAllocationBean.setWorkRequisitionNo(sqmAllocation.getWork().getWorkRequisitionNo());

		return sqmAllocationBean;
	}

