	@Override
	public WorkLoggingJson fetchHistoryWorkLegacy(Pageable pageable, Long workId,

			String loggedInUserRole, String username) {
		WorkLoggingJson workJson = null;

		try {
			Page<WorkLogging> worksLogging = null;

			if (loggedInUserRole.equals(RESConstants.ROLE_EE)) {

				worksLogging = workLoggingRepository.findById(pageable, workId);
			} else if (loggedInUserRole.equals(RESConstants.ROLE_CE)) {

				worksLogging = workLoggingRepository.findById(pageable, workId);
			} else if (loggedInUserRole.equals(RESConstants.ROLE_EnC)) {

				worksLogging = workLoggingRepository.findById(pageable, workId);
			}

			if (worksLogging != null) {
				List<WorkLogging> entityList = worksLogging.getContent();
				List<WorkLoggingBean> beanList = new ArrayList<>();
				if (entityList != null && !entityList.isEmpty()) {

					int index = pageable.getPageNumber() * pageable.getPageSize();
					for (WorkLogging work : entityList) {
						Work works = workRepository.findOne(workId);

						WorkLoggingBean bean = convertWorkLoggingEntityToBeanDuringListing(work, works);
						bean.setIndex(++index);
						beanList.add(bean);
					}
				}
				workJson = new WorkLoggingJson();
				workJson.setiTotalDisplayRecords(worksLogging.getTotalElements());
				// workJson.setiTotalRecords(workRepository.countByStatusNotAndIsOICNotNull(RESConstants.STATUS_DELETED));

				workJson.setiTotalRecords(worksLogging.getTotalElements());

				workJson.setAaData(beanList);
			}
			return workJson;
		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return workJson;
		}
	}

