	@Override
	public List<WorkBean> getWorkList(Short isLegacy, String role, Long officeId, Long userId) {
		try {
			List<Work> entityList = null;
			List<WorkBean> beanList = new ArrayList<>();
			if (role.equals(RESConstants.ROLE_ADMIN)) {
				entityList = workRepository.findByIsLegacy((short) 1);

			}

			else if (role.equals(RESConstants.ROLE_CE)) {
				entityList = workRepository.findByIsLegacyAndStatusAndChiefEngineerOfficeId(isLegacy,
						RESConstants.REQUEST_STATUS_SUBMITTED, officeId);

			} else if (role.equals(RESConstants.ROLE_EE)) {
				entityList = workRepository.findByIsLegacyAndExecutiveEngineerOfficeId(isLegacy, officeId);
			} else if (role.equals(RESConstants.ROLE_SUPDT_ENGG)) {
				entityList = workRepository.findByIsLegacyAndExecutiveEngineerOfficeId(isLegacy, officeId);
			} else if (role.equals(RESConstants.ROLE_SUB_ENGG)) {
				entityList = workRepository.findByIsLegacyAndSubEngineerUserIdAndOfficeId(isLegacy, userId, officeId);

			} else if (role.equals(RESConstants.ROLE_AE)) {
				entityList = workRepository.findByIsLegacyAndAssistantEngineerUserIdAndOfficeId(isLegacy, userId,
						officeId);
			} else if (role.equals(RESConstants.ROLE_DIR_GP)) {
				entityList = workRepository.findWorkListByIsLegacyAndLineDepartmentId(isLegacy, (long) 17);
			} else {
				entityList = workRepository.findAll();
			}

			if (entityList != null) {

				if (entityList != null && !entityList.isEmpty()) {

					for (Work work : entityList) {

						WorkBean bean = convertWorkEntityToBean(work);
						beanList.add(bean);
					}
				}

			}
			return beanList;
		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return null;
		}
	}

