	@Override
	public BillLoggingBean fetchOriginalBillDetails(Long id) {
		BillLoggingBean billBean = null;
		try {

			BillLogging billEntity = billLoggingRepository.findByBillAndStatus(new Bill(id),
					new MasterBillStatus(RESConstants.STATUS_PHYSICAL_INSPECTION_COMPLETED_ID));
			billBean = convertBillLoggingEntityToBean(billEntity);

			List<BillItemsLogging> billItemsEntityList = billItemsLoggingRepository.findByBill(new Bill(id));
			List<BillItemLoggingBean> billItemList = new ArrayList<BillItemLoggingBean>();

			BillItemLoggingBean billItemBean = null;
			for (BillItemsLogging billItems : billItemsEntityList) {
				billItemBean = convertBillItemsLoggingEntityToBean1(billItems);
				billItemList.add(billItemBean);
			}

			billBean.setBillItems(billItemList);

		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return null;
		}

		return billBean;
	}

