	@Override
	public InspectionCompletedWorkBeanNew fetchInspectionCompletedBillsNew(Long id, Long inspectedBy) {

		InspectionCompletedWorkBeanNew inspectionCompletedWorkBean = new InspectionCompletedWorkBeanNew();

		/*
		 * ======================= FETCH ANSWERS =======================
		 */
		List<InspectionAnswersNew> inspectionAnswers = inspectionAnswerRepositoryNew
				.findByInspection(new InspectionDetails(id));

		List<InspectionAnswerNewBean> answerBeanList = new ArrayList<>();

		for (InspectionAnswersNew entity : inspectionAnswers) {
			answerBeanList.add(convertInspectionAnswerEntitiyToBean(entity));
		}

		inspectionCompletedWorkBean.setInspectionAnswerNewBean(answerBeanList);

		/*
		 * ======================= FETCH IMAGES =======================
		 */
		List<ImageBean> imageList = new ArrayList<>();

		List<InspectionAnswerImageNew> images = inspectionAnswerImageRepositoryNew.findByInspectionId(id);

		for (InspectionAnswerImageNew iai : images) {
			ImageBean ib = new ImageBean();
			ib.setImageUrl(iai.getDocumentUpload().getDocumentName());
			ib.setImageName(iai.getDocumentUpload().getDocumentName());
			setDownloadURL1(ib);
			imageList.add(ib);
		}

		inspectionCompletedWorkBean.setImageBean(imageList);

		return inspectionCompletedWorkBean;
	}

	private InspectionAnswerNewBean convertInspectionAnswerEntitiyToBean(InspectionAnswersNew entity) {

		InspectionAnswerNewBean bean = new InspectionAnswerNewBean();
		bean.setInspectionId(entity.getInspection().getId());
		bean.setQuestionId(entity.getQuestionId());
		bean.setAnswer(entity.getAnswer());
		bean.setInspectionTypeId(entity.getInspectionTypeId());
		return bean;
	}

