	// fetchInspectionCompletedWorksCC
	@Override
	public InspectionCompletedWorkBean fetchInspectionCompletedWorksCC(Long workid, String inspectedBy) {
		BillBean billBean = null;
		InspectionCompletedWorkBean inspectionCompletedWorkBean = new InspectionCompletedWorkBean();
		/*
		 * List<InspectionAnswer> inspectionAnswer =
		 * inspectionAnswerRepository.findByBillAndAnswerBy(new Bill(billId),new
		 * Users(inspectedBy));
		 */

		List<Object[]> entityList = null;
		Users u = userRepository.findByEmailId(inspectedBy);
		entityList = inspectionAnswerRepositoryCC.findByWorkAndInspectedby(workid, inspectedBy, u.getId());
		List<InspectionAnswerBean> list = new ArrayList<InspectionAnswerBean>();

		if (entityList != null && !entityList.isEmpty()) {

			for (Object[] objArr : entityList) {

				InspectionAnswerBean bean = new InspectionAnswerBean();
				bean.setId(Long.parseLong(objArr[0].toString()));
				bean.setCode((String) objArr[1]);
				bean.setQuestionText((String) objArr[2]);
				if (objArr[3] != null) {
					bean.setAnswer((String) objArr[3]);
				}
				bean.setWorkId(Long.parseLong(objArr[4].toString()));
				if (objArr[5] != null) {
					bean.setAnswerByName((String) objArr[5]);
				}

				list.add(bean);
			}
		}

		InspectionAnswerBean bean = null;

		List<ImageBean> imageList = new ArrayList<ImageBean>();
		inspectionCompletedWorkBean.setInspectionAnswerBean(list);

		List<Object[]> entityListImage = null;
		entityListImage = inspectionAnswerImageRepositoryCC.findDocumentId(workid, inspectedBy, u.getId());

		if (entityListImage != null && !entityListImage.isEmpty()) {

			for (Object[] objArr : entityListImage) {

				ImageBean imageBean = new ImageBean();
				if (objArr[0] != null) {
					imageBean.setImageName((String) objArr[0]);
				}
				setDownloadURL1(imageBean);
				imageList.add(imageBean);
			}
		}

		inspectionCompletedWorkBean.setImageBean(imageList);
		return inspectionCompletedWorkBean;
	}

