	@Override
	public void updateBillStatus(Long billId, Long status) {

		Bill bill = billRepository.findOne(billId);
		bill.setStatus(new MasterBillStatus(status));
		billRepository.saveAndFlush(bill);
		if (RESConstants.STATUS_FWD_FOR_PAYMENT_ID.equals(status)
				&& bill.getBillType().equals(RESConstants.BILL_TYPE_FINAL)) {
			Work workEntity = workRepository.findOne(bill.getWork().getId());
			if (workEntity.getWorkRequestStatusId().getId()
					.equals(RESConstants.REQUEST_STATUS_Initiated_CC_Fwd_for_Final_Inspection_ID)) {
				workEntity.setWorkRequestStatusId(
						new RequestStatus(RESConstants.REQUEST_STATUS_Final_Inspecion_Completed_ID));
				workRepository.saveAndFlush(workEntity);
			}
		}
	}

	public void updateBillStatusForRunningAndFinalBill(Long billId, Long status, String role) {

		Bill bill = billRepository.findOne(billId);
		if (bill.getBillType().equals(RESConstants.BILL_TYPE_RUNNING)) {
			bill.setStatus(new MasterBillStatus(status));
			bill.setInspectedByDatetime(new Date());
		} else if (bill.getBillType().equals(RESConstants.BILL_TYPE_FINAL)) {
			if (RESConstants.ROLE_AE.equals(role) || RESConstants.ROLE_SUB_ENGG.equals(role)) {
				bill.setInspectedByDatetime(new Date());
				if (null != bill.getInspectedByEeDatetime()) {
					bill.setStatus(new MasterBillStatus(status));
				}
			} else if (RESConstants.ROLE_EE.equals(role)) {
				bill.setInspectedByEeDatetime(new Date());
				if (null != bill.getInspectedByDatetime()) {
					bill.setStatus(new MasterBillStatus(status));
				}
			}
		}
		billRepository.saveAndFlush(bill);
	}

	@Override
	public void rejectBill(BillBean billBean, String role) {
		Bill bill = billRepository.findOne(billBean.getId());
		if (role.equals("ROLE_SUB_ENGG")) {
			bill.setSubEnggRemark(billBean.getRemark());
		} else {
			bill.setRemark(billBean.getRemark());
		}
		bill.setStatus(new MasterBillStatus(RESConstants.STATUS_FINAL_BILL_REJECTED_ID));
		billRepository.saveAndFlush(bill);
	}

	private void updateWorkPhysicalStage(Long billId, String physicalStage) {
		if (null != physicalStage && !("").equals(physicalStage)) {

			Bill billEntity = billRepository.findOne(billId);
			Work workEntity = workRepository.findOne(billEntity.getWork().getId());
			workEntity.setPhysicalStageType(new PhysicalStageType(Long.parseLong(physicalStage)));
			if (billEntity.getBillType().equals(RESConstants.BILL_TYPE_FINAL)
					&& billEntity.getStatus().getStatusId().equals(RESConstants.STATUS_PHYSICAL_INSPECTION_COMPLETED_ID)
					&& workEntity.getWorkRequestStatusId().getId()
							.equals(RESConstants.REQUEST_STATUS_Initiated_CC_Fwd_for_Final_Inspection_ID)) {
				workEntity.setWorkRequestStatusId(
						new RequestStatus(RESConstants.REQUEST_STATUS_Final_Inspecion_Completed_ID));
			}
			workRepository.saveAndFlush(workEntity);
		}
	}

	private void updateWorkPhysicalStageViaWorkId(Long workId, String physicalStage) {
		if (null != physicalStage && !("").equals(physicalStage)) {

			Work workEntity = workRepository.findOne(workId);
			workEntity.setPhysicalStageType(new PhysicalStageType(Long.parseLong(physicalStage)));
			workRepository.saveAndFlush(workEntity);
		}
	}

	private void updateWorkPhysicalStage(Long billId, String physicalStage, String completedLength) {
		if (null != physicalStage && !("").equals(physicalStage)) {

			Bill billEntity = billRepository.findOne(billId);
			Work workEntity = workRepository.findOne(billEntity.getWork().getId());

			workEntity.setPhysicalStageType(new PhysicalStageType(Long.parseLong(physicalStage)));

			if (completedLength != null) {
				workEntity.setCompleteddistance(new BigDecimal(completedLength));
			}

			workRepository.saveAndFlush(workEntity);
		}
	}

	private void updateWorkPhysicalStageViaWorkId(Long workId, String physicalStage, String completedLength) {
		if (null != physicalStage && !("").equals(physicalStage)) {

			Work workEntity = workRepository.findOne(workId);

			workEntity.setPhysicalStageType(new PhysicalStageType(Long.parseLong(physicalStage)));

			if (completedLength != null) {
				workEntity.setCompleteddistance(new BigDecimal(completedLength));
			}

			workRepository.saveAndFlush(workEntity);
		}
	}

	@Override
	@Transactional(rollbackFor = Exception.class)
	public String savePaymentData(PaymentBean bean) {

		try {
			if (bean != null) {
				PaymentTable entity = new PaymentTable();

				entity.setCashbookVoucherNo(bean.getCashbookVoucherNo());
				if (bean.getCashbookDate() != null) {
					entity.setCashbookDate(RESUtil.convertStringToDate(bean.getCashbookDate()));
				}

				entity.setBill(new Bill(bean.getBillId()));
				paymentRepository.save(entity);

				if (bean.getPaymentDetailBeanList() != null && !bean.getPaymentDetailBeanList().isEmpty()) {

					PaymentDetail paymentDetail = null;
					for (PaymentDetailBean paymentDetailBean : bean.getPaymentDetailBeanList()) {

						paymentDetail = new PaymentDetail();
						paymentDetail.setAmount(paymentDetailBean.getAmount());

						if (null != paymentDetailBean.getBankId()) {
							paymentDetail.setBankId(new Bank(paymentDetailBean.getBankId()));
						}

						paymentDetail.setInstrumentDate(paymentDetailBean.getInstrumentDate());

						paymentDetail.setInstrumentNo(paymentDetailBean.getInstrumentNo());

						paymentDetail.setPaymentMode(paymentDetailBean.getPaymentMode());

						paymentDetail.setPaymentTable(entity);

						paymentDetailRepository.save(paymentDetail);
					}
				}
			}

		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return RESConstants.ERROR_SAVING_DATA;
		}
		if (null != bean) {
			updateBillStatus(bean.getBillId(), RESConstants.STATUS_PAYMENT_COMPLETED_ID);
		}
		return null;
	}

	@Override
	@Transactional(rollbackFor = Exception.class)
	public String saveContengencyData(ContengencyBean bean) {

		try {
			if (bean != null) {
				ContengencyTable entity = new ContengencyTable();

				entity.setExpenditureAmount(bean.getExpenditureAmount());
				if (bean.getExpenditureDate() != null) {
					entity.setExpenditureDate(RESUtil.convertStringToDate(bean.getExpenditureDate()));
				}

				entity.setRemarks(bean.getRemarks());
				entity.setBill(new Bill(bean.getBillId()));
				entity.setCreatedDate(new Date());

				Bill bill = billRepository.findOne(bean.getBillId());
				entity.setWork(bill.getWork());

				contengencyRepository.save(entity);
			}

		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return RESConstants.ERROR_SAVING_DATA;
		}

		if (null != bean) {
			updateBillStatus(bean.getBillId(), RESConstants.STATUS_CONTENGENCY_COMPLETED_ID);
		}
		return null;
	}

