	@Override
	public PaymentBean fetchPaymentData(Long billId) {

		PaymentBean paymentBean = new PaymentBean();

		/*
		 * PaymentTable paymentTable = paymentRepository.findByBill( new
		 * Bill(billId)).get(0);
		 */

		List<PaymentTable> payment = paymentRepository.findByBill(new Bill(billId));

		if (payment != null && !payment.isEmpty()) {
			PaymentTable paymentTable = payment.get(0);

			/* PaymentBean paymentBean = new PaymentBean(); */

			paymentBean.setCashbookVoucherNo(paymentTable.getCashbookVoucherNo());
			paymentBean.setCashbookDate(RESUtil.convertDateToString(paymentTable.getCashbookDate()));
			paymentBean.setBillId(billId);
			paymentBean.setId(paymentTable.getId());

			List<PaymentDetail> list = paymentDetailRepository.findByPaymentTable(paymentTable);

			List<PaymentDetailBean> paymentDetailBeanList = new ArrayList<PaymentDetailBean>();

			PaymentDetailBean paymentDetailBean = null;

			for (PaymentDetail paymentDetail : list) {
				paymentDetailBean = new PaymentDetailBean();

				paymentDetailBean.setAmount(paymentDetail.getAmount());

				if (paymentDetail.getBankId() != null) {
					paymentDetailBean.setBankName(paymentDetail.getBankId().getBankName());
					paymentDetailBean.setBankId(paymentDetail.getBankId().getBankId());
				}

				paymentDetailBean.setInstrumentDate(paymentDetail.getInstrumentDate());
				paymentDetailBean.setInstrumentNo(paymentDetail.getInstrumentNo());
				paymentDetailBean.setPaymentMode(paymentDetail.getPaymentMode());

				paymentDetailBean.setPaymentTableId(paymentDetail.getPaymentTable().getId());
				paymentDetailBeanList.add(paymentDetailBean);
			}

			paymentBean.setPaymentDetailBeanList(paymentDetailBeanList);
		}

		return paymentBean;

	}

	@Override
	public List<ContengencyBean> fetchPrevContengecyData(Long billId) {

		ContengencyBean contengencyBean = null;

		Bill bill = billRepository.getOne(billId);
		Work work = workRepository.getOne(bill.getWork().getId());
		List<ContengencyTable> contengencyTableList = contengencyRepository.findByWork(work);
		List<ContengencyBean> contengencyBeanList = new ArrayList<ContengencyBean>();

		for (ContengencyTable contengencyTable : contengencyTableList) {
			contengencyBean = new ContengencyBean();
			convertContengencyTableToContengencyBean(contengencyTable, contengencyBean);
			contengencyBeanList.add(contengencyBean);
		}

		return contengencyBeanList;
	}

	private void convertContengencyTableToContengencyBean(ContengencyTable contengencyTable,
			ContengencyBean contengencyBean) {

		contengencyBean.setExpenditureAmount(contengencyTable.getExpenditureAmount());
		contengencyBean.setExpenditureDate(RESUtil.convertDateToString(contengencyTable.getExpenditureDate()));
		contengencyBean.setRemarks(contengencyTable.getRemarks());
		contengencyBean.setBillId(contengencyTable.getBill().getId());
		contengencyBean.setId(contengencyTable.getId());

	}

	public ContengencyBean fetchContengecyData(Long billId) {

		ContengencyBean contengencyBean = new ContengencyBean();

		if (contengencyRepository.findByBill(new Bill(billId)).size() > 0) {

			ContengencyTable contengencyTable = contengencyRepository.findByBill(new Bill(billId)).get(0);

			contengencyBean.setExpenditureAmount(contengencyTable.getExpenditureAmount());
			contengencyBean.setExpenditureDate(RESUtil.convertDateToString(contengencyTable.getExpenditureDate()));
			contengencyBean.setRemarks(contengencyTable.getRemarks());
			contengencyBean.setBillId(billId);
			contengencyBean.setId(contengencyTable.getId());
		}

		// Prev
		List<ContengencyBean> list = fetchPrevContengecyData(billId);
		int commulativeExpenditure = 0;
		for (ContengencyBean contengencyBean1 : list) {
			commulativeExpenditure = commulativeExpenditure + contengencyBean1.getExpenditureAmount();
		}

		contengencyBean.setOldContengencyBeanList(list);
		contengencyBean.setCommulativeExpenditure(commulativeExpenditure);
		return contengencyBean;

	}

