	private TechnicalSanction convertTechnicalSanctionBeanToEntity(TechnicalSanction technicalSanctionEntity,
			TechnicalSanctionBean technicalSanctionBean) throws RESBusinessException {

		// competent authority changes
		technicalSanctionEntity.setCompetentAuthDesig(technicalSanctionBean.getCompetentAuthDesig());
		technicalSanctionEntity.setCompetentAuthName(technicalSanctionBean.getCompetentAuthName());

		if (technicalSanctionBean.getTechnicalSanctionNo() != null)
			technicalSanctionEntity.setTechnicalSanctionNo(technicalSanctionBean.getTechnicalSanctionNo());

		if (technicalSanctionBean.getTsDispatchNumber() != null)
			technicalSanctionEntity.setTsDispatchNumber(technicalSanctionBean.getTsDispatchNumber());

		if (technicalSanctionBean.getTechnicalSanctionNoOld() != null)
			technicalSanctionEntity.setTechnicalSanctionNoOld(technicalSanctionBean.getTechnicalSanctionNoOld());

		if (technicalSanctionBean.getTechnicalSanctionDate() != null)
			technicalSanctionEntity.setTechnicalSanctionDate(
					RESUtil.convertStringToDate(technicalSanctionBean.getTechnicalSanctionDate()));

		if (technicalSanctionBean.getTsDispatchDate() != null)
			technicalSanctionEntity
					.setTsDispatchDate(RESUtil.convertStringToDate(technicalSanctionBean.getTsDispatchDate()));

		if (technicalSanctionBean.getIsCeOfficeName() != null)
			technicalSanctionEntity.setIsCeOfficeName(technicalSanctionBean.getIsCeOfficeName());

		if (technicalSanctionBean.getIsSeOfficeName() != null)
			technicalSanctionEntity.setIsSeOfficeName(technicalSanctionBean.getIsSeOfficeName());

		if (technicalSanctionBean.getIsDistrictName() != null)
			technicalSanctionEntity.setIsDistrictName(technicalSanctionBean.getIsDistrictName());

		if (technicalSanctionBean.getIsGrampanchayatName() != null)
			technicalSanctionEntity.setIsGrampanchayatName(technicalSanctionBean.getIsGrampanchayatName());

		if (technicalSanctionBean.getIsLinedepartmentName() != null)
			technicalSanctionEntity.setIsLinedepartmentName(technicalSanctionBean.getIsLinedepartmentName());

		if (technicalSanctionBean.getIsEeOfficeName() != null)
			technicalSanctionEntity.setIsEeOfficeName(technicalSanctionBean.getIsEeOfficeName());

		technicalSanctionEntity
				.setTechnicalStatus(new TechnicalStatus(technicalSanctionBean.getTechnicalSanctionStatusId()));

		if (technicalSanctionBean.getTechnicalSanctionTypeBean() != null) {
			technicalSanctionEntity.setTechnicalSanctionType(new TechnicalSanctionType(
					technicalSanctionBean.getTechnicalSanctionTypeBean().getTechnicalSanctionTypeId()));

		}

		technicalSanctionEntity.setTechnicalSanctionAmount(technicalSanctionBean.getTechnicalSanctionAmount());

		if (technicalSanctionBean.getTechnicalSanctionTypeBean() != null) {

			TechnicalSanctionType technicalSanctionType = new TechnicalSanctionType();

			if ("ORIGINAL".equals(technicalSanctionBean.getTechnicalSanctionTypeBean().getTechnicalSanctionType())) {
				technicalSanctionType.setTechnicalSanctionTypeId(RESConstants.TS_TYPE_STATUS_ORIGINAL);
			} else if ("REVISED"
					.equals(technicalSanctionBean.getTechnicalSanctionTypeBean().getTechnicalSanctionType())) {
				technicalSanctionType.setTechnicalSanctionTypeId(RESConstants.TS_TYPE_STATUS_REVISED);
			}

			technicalSanctionEntity.setTechnicalSanctionType(technicalSanctionType);
		}

		return technicalSanctionEntity;

	}

