	private String convertAnswer4(String ans) {

		if (ans == null) {
			return "";
		}

		switch (ans) {
		case "true":
			return "Yes";
		case "false":
			return "No";

		default:
			return "";
		}
	}

	private String convertAnswerfnonf(String ans) {

		if (ans == null) {
			return "";
		}

		switch (ans) {
		case "feasible":
			return "Feasible";
		case "nonfeasible":
			return "Non Feasible";

		default:
			return "";
		}
	}

	private String convertAnswersow(String ans) {

		if (ans == null) {
			return "";
		}

		switch (ans) {
		case "1":
			return "I";
		case "2":
			return "II";
		case "3":
			return "III";
		case "4":
			return "IV";

		default:
			return "";
		}
	}

