			JSONObject gr7json = (JSONObject) data.get("group7");
			com.res.entity.talab.Group7 group7 = g.fromJson(gr7json.toString(), com.res.entity.talab.Group7.class);

			JSONObject gr10json = (JSONObject) data.get("overallObservation");
			com.res.entity.sqm.OverallObservation overallObservation = g.fromJson(gr10json.toString(),
					com.res.entity.sqm.OverallObservation.class);

			/* Long billId = Long.valueOf(datajson.getId()); */
			InspectionAnswer inspectionAnswer = new InspectionAnswer();

			String name = null;
			String post = null;
			String adhikariNameNPost = group1.getAdhikariNameNPost();
