	@Override
	public void updateWorkRequisitionScript() {

		// List<Work> workList = workRepository.findAll();

		System.out.println("Started....");

		List<Work> workList = workRepository.findByIsLegacy((short) 1);
		int i = 0;

		long start = System.currentTimeMillis();

		for (Work entity : workList) {

			i++;

			String lastWord = entity.getExecutiveEngineerOffice().getOfficeName()
					.substring(entity.getExecutiveEngineerOffice().getOfficeName().lastIndexOf(",") + 1);
			if (entity.getAgencyTypeId().getAgencyTypeId() == 1) {
				lastWord = "LD_" + lastWord + "_RC";
			} else if (entity.getAgencyTypeId().getAgencyTypeId() == 2) {
				lastWord = "LD_" + lastWord + "_GP";
			} else if (entity.getAgencyTypeId().getAgencyTypeId() == 3) {
				lastWord = "LD_" + lastWord + "_RD";
			}

			WorkLegacyIdGeneration workLegacyIdGeneration = workLegacyIdGenerationRepository
					.findByDivisionAgency(lastWord);

			if (workLegacyIdGeneration == null) {
				entity.setWorkRequisitionNo(lastWord + "_1");
				persistFirstLegacyIdGeneration(lastWord, 1);
			} else {
				int newCount = workLegacyIdGeneration.getCounter() + 1;
				workLegacyIdGeneration.setCounter(newCount);
				workLegacyIdGenerationRepository.save(workLegacyIdGeneration);
				entity.setWorkRequisitionNo(lastWord + "_" + newCount);
			}

		} // /for loop

		workRepository.save(workList);

		System.out.println("total record found in DB : " + workList.size());
		System.out.println("total record updated in DB: " + i);

		long elapsedTimeMillis = System.currentTimeMillis() - start;

		// Get elapsed time in minutes
		float elapsedTimeMin = elapsedTimeMillis / (60 * 1000F);
		System.out.println(elapsedTimeMin);

	}

