	@Override
	public List<InspectionSqmAnswerBean> fetchInspectionAnswerSqmByWorkId(Long sqmAllocationId) {

		List<InspectionSqmAnswer> list = inspectionSqmAnswerRepository
				.findInspectionAnswersForSqmBySqmAllocationId(new SqmAllocation(sqmAllocationId));

		List<InspectionSqmAnswerBean> inspectionSqmAnswerBean = new ArrayList<>();
		if (list != null) {
			Integer counter = 1;
			Integer index = 0;

			for (InspectionSqmAnswer item : list) {

				InspectionSqmAnswerBean inspectionBean = new InspectionSqmAnswerBean();
				convertInspectionSqmAnswerEntityToBean(item, inspectionBean);
				inspectionSqmAnswerBean.add(inspectionBean);

				int cululativeChildCount = 0;
				if (item.getParentId() == null) {
					inspectionBean.setSerialNo(counter);
					counter++;
					List<InspectionSqmAnswerBean> inspectionSqmAnswerBean2 = new LinkedList<InspectionSqmAnswerBean>();

					int lastItemCount1 = 0;
					for (InspectionSqmAnswer child : item.getChildItems()) {
						cululativeChildCount++;
						int cululativeChildCount1 = 0;
						InspectionSqmAnswerBean inspectionSqmAnswerBean1 = new InspectionSqmAnswerBean();

						inspectionSqmAnswerBean1.setIndex(index);
						inspectionSqmAnswerBean1.setIsaparentId(inspectionBean.getId());
						inspectionSqmAnswerBean1.setParentIndex(inspectionBean.getIndex());
						if (null != inspectionBean.getGroup()) {
							inspectionSqmAnswerBean1.setLeafNode(true);
						}
						convertInspectionSqmAnswerEntityToBean(child, inspectionSqmAnswerBean1);
						inspectionSqmAnswerBean2.add(inspectionSqmAnswerBean1);
						inspectionSqmAnswerBean.add(inspectionSqmAnswerBean1);
						index++;

						// settingLastItemFlag in WorkTemplateBean.
						if (item.getChildItems().size() == lastItemCount1 + 1) {
							inspectionSqmAnswerBean1.setLastElement(true);
						}
						lastItemCount1++;
						// close here.

						inspectionBean.setChildItems(inspectionSqmAnswerBean2);
						inspectionBean.setChildsCount(inspectionSqmAnswerBean2.size());

						// second
						List<InspectionSqmAnswerBean> inspctionSqmAnswerBean3 = new LinkedList<InspectionSqmAnswerBean>();

						int lastItemCount2 = 0;
						for (InspectionSqmAnswer child2 : child.getChildItems()) {
							cululativeChildCount++;
							cululativeChildCount1++;
							InspectionSqmAnswerBean workTemplateBean2 = new InspectionSqmAnswerBean();

							workTemplateBean2.setIndex(index);
							workTemplateBean2.setIsaparentId(inspectionSqmAnswerBean1.getId());
							workTemplateBean2.setParentIndex(inspectionSqmAnswerBean1.getIndex());
							workTemplateBean2.setLeafNode(true);

							convertInspectionSqmAnswerEntityToBean(child2, workTemplateBean2);
							inspctionSqmAnswerBean3.add(workTemplateBean2);
							inspectionSqmAnswerBean.add(workTemplateBean2);
							inspectionSqmAnswerBean1.setChildItems(inspctionSqmAnswerBean3);
							inspectionSqmAnswerBean1.setChildsCount(inspctionSqmAnswerBean3.size());
							index++;

							// settingLastItemFlag in WorkTemplateBean.
							if (child.getChildItems().size() == lastItemCount2 + 1) {
								workTemplateBean2.setLastElement(true);
							}
							lastItemCount2++;
							// close here.

							List<InspectionSqmAnswerBean> inspctionSqmAnswerBean4 = new LinkedList<InspectionSqmAnswerBean>();

							for (InspectionSqmAnswer child3 : child2.getChildItems()) {
								cululativeChildCount++;
								cululativeChildCount1++;
								InspectionSqmAnswerBean workTemplateBean3 = new InspectionSqmAnswerBean();

								workTemplateBean3.setIndex(index);
								workTemplateBean3.setIsaparentId(workTemplateBean2.getId());
								workTemplateBean3.setParentIndex(workTemplateBean2.getIndex());
								workTemplateBean3.setLeafNode(true);

								convertInspectionSqmAnswerEntityToBean(child3, workTemplateBean3);
								inspctionSqmAnswerBean4.add(workTemplateBean3);
								inspectionSqmAnswerBean.add(workTemplateBean3);
								inspectionSqmAnswerBean1.setChildItems(inspctionSqmAnswerBean4);
								inspectionSqmAnswerBean1.setChildsCount(inspctionSqmAnswerBean4.size());
								index++;

								// settingLastItemFlag in WorkTemplateBean.
								if (child.getChildItems().size() == lastItemCount2 + 1) {
									workTemplateBean2.setLastElement(true);
								}
								lastItemCount2++;
								// close here.
							}
						}
						inspectionSqmAnswerBean1.setCumulativeChildsCount(cululativeChildCount1);
					}
				}
				inspectionBean.setCumulativeChildsCount(cululativeChildCount);
			}
		}
		return inspectionSqmAnswerBean;
	}

