	private void convertInspectionSqmAnswerEntityToBean(InspectionSqmAnswer item,
			InspectionSqmAnswerBean templateBean) {

		templateBean.setId(item.getId());
		templateBean.setAnswer(item.getAnswer());
		templateBean.setQuestionText(item.getQuestionText());
		templateBean.setInspectionSqmId(item.getSqmAllocationId().getId());
		templateBean.setGroup(item.getGroup());

	}

