	private String convertAnswer1(String ans) {

		if (ans == null) {
			return "";
		}

		switch (ans) {
		case "1":
			return "हाँ";
		case "2":
			return "नहीं";
		case "3":
			return "N/A";
		default:
			return "";
		}
	}

