	// Nickel tender
	@Override
	public String addTender(WorkTenderBean tenderBean, String role) {
		try {
			WorkTender entity = new WorkTender();
			convertTenderBeanToTenderEntityEntity(entity, tenderBean);
			// Rakesh code for Parent Id
			// WorkTender parentEntity=
			// workTenderRepository.findByWorkId(tenderBean.getWorkId()).get(0);
			WorkTender parentEntity = (workTenderRepository.findByWorkIdOrderByCreatedDateDesc(tenderBean.getWorkId())
					.size() > 0 ? workTenderRepository.findByWorkIdOrderByCreatedDateDesc(tenderBean.getWorkId()).get(0)
							: null);

			if (parentEntity != null) {
				entity.setParentId(parentEntity);
			}
			WorkTender workTender = workTenderRepository.save(entity);

			for (ContractorDepositBean contractorDepositBean : tenderBean.getContratorDepositsList()) {
				ContractorDeposit contractorDeposit = new ContractorDeposit();
				convertContractorDepositBeanToContractorDepositEntityEntity(contractorDeposit, contractorDepositBean);
				contractorDeposit.setWorkTender(entity);
				contractorDepositRepository.save(contractorDeposit);
			}

			if (tenderBean.getTenderStatusId() == 2) {
				Work work = workRepository.findOne(tenderBean.getWorkId());
				work.setWorkRequestStatusId(new RequestStatus(RESConstants.REQUEST_STATUS_FWD_FOR_AGGREEMENT_ID));
				workRepository.save(work);
			}
			if (role.equals(RESConstants.ROLE_EnC)) {

				WorkAgreement workAgreement = new WorkAgreement();
				// convertWorkAgreementBeanToEntity(workAgreement, workAgreementBean);
				WorkAgreement parentWorkAgreement = workAgreementRepository
						.findByWorkOrderByCreatedDateDesc(new Work(workTender.getWork().getId())).size() > 0
								? workAgreementRepository
										.findByWorkOrderByCreatedDateDesc(new Work(workTender.getWork().getId())).get(0)
								: null;
				if (parentWorkAgreement != null) {
					convertWorkAgreementBeanToEntity(workAgreement, parentWorkAgreement);
					workAgreement.setParentId(parentWorkAgreement);
					workAgreement.setWorkTender(workTender);
					// parentWorkAgreement.setId(null);

					// WorkAgreement agreement = parentWorkAgreement;
					WorkAgreement wagment = workAgreementRepository.save(workAgreement);

					List<WorkFinancialMileStone> workFinancialMileStoneEntityList = workFinancialMileStoneRepository
							.findByWorkAgreement(parentWorkAgreement);
					if (workFinancialMileStoneEntityList != null) {
						for (WorkFinancialMileStone workFinancialMileStoneEntity : workFinancialMileStoneEntityList) {
							WorkFinancialMileStone workFinancialMileStone = new WorkFinancialMileStone();
							convertWorkFinancialMileStoneEntityToEntity(workFinancialMileStone,
									workFinancialMileStoneEntity);
							workFinancialMileStone.setWorkAgreement(wagment);
							workFinancialMileStoneRepository.save(workFinancialMileStone);
						}
					}

					List<WorkPhysicalMileStone> workPhysicalMileStoneEntityList = workPhysicalMileStoneRepository
							.findByWorkAgreement(parentWorkAgreement);
					if (workPhysicalMileStoneEntityList != null) {
						for (WorkPhysicalMileStone workPhysicalMileStoneEntity : workPhysicalMileStoneEntityList) {
							WorkPhysicalMileStone workPhysicalMileStone = new WorkPhysicalMileStone();
							convertWorkPhysicalMileStoneEntityToEntity(workPhysicalMileStone,
									workPhysicalMileStoneEntity);
							workPhysicalMileStone.setWorkAgreement(wagment);
							workPhysicalMileStoneRepository.save(workPhysicalMileStone);
						}
					}

					if (parentWorkAgreement.getStatus().getStatusId() == 2) {
						Work work = workRepository.findOne(parentWorkAgreement.getWork().getId());
						work.setWorkStatusId(new WorkStatus(RESConstants.STATUS_IN_PROGRESS_ID));
						work.setWorkRequestStatusId(new RequestStatus(
								RESConstants.REQUEST_STATUS_WORK_AGREEMENT_DONE_FWD_FOR_BILLING_INSPECTION_ID));
						workRepository.save(work);
					}

				}
			}

		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return RESConstants.ERROR_SAVING_DATA;
		}
		return null;
	}

	// Nickel tender
	@Override
	public String editTender(WorkTenderBean tenderBean) {
		try {

			WorkTender entity = workTenderRepository
					.findByAdministrationSanction(new AdministrationSanction(tenderBean.getAdministrationSanctionId()));
			convertTenderBeanToTenderEntityEntity(entity, tenderBean);
			workTenderRepository.save(entity);

			List<ContractorDeposit> list = contractorDepositRepository.findByWorkTender(entity);
			contractorDepositRepository.deleteInBatch(list);

			for (ContractorDepositBean contractorDepositBean : tenderBean.getContratorDepositsList()) {
				ContractorDeposit contractorDeposit = new ContractorDeposit();
				convertContractorDepositBeanToContractorDepositEntityEntity(contractorDeposit, contractorDepositBean);
				contractorDeposit.setWorkTender(entity);
				contractorDepositRepository.save(contractorDeposit);
			}

			if (tenderBean.getTenderStatusId() == 2) {
				Work work = workRepository.findOne(tenderBean.getWorkId());
				work.setWorkRequestStatusId(new RequestStatus(RESConstants.REQUEST_STATUS_FWD_FOR_AGGREEMENT_ID));
				workRepository.save(work);
			}

		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return RESConstants.ERROR_SAVING_DATA;
		}
		return null;
	}

	private void convertTenderBeanToTenderEntityEntity(WorkTender entity, WorkTenderBean tenderBean)
			throws RESBusinessException {
		entity.setAdministrationSanction(new AdministrationSanction(tenderBean.getAdministrationSanctionId()));
		entity.setAmountOfContract(tenderBean.getAmountOfContract());
		entity.setContractorId(new Contractor(tenderBean.getContractorId()));
		entity.setNoOFparticipants(tenderBean.getNoOFparticipants());
		entity.setTenderCost(tenderBean.getTenderCost());
		entity.setTenderNumber(tenderBean.getTenderNumber());
		entity.setTenderOpeningDate(RESUtil.convertStringToDate(tenderBean.getTenderOpeningDate()));
		entity.setStatus(new TenderStatus(tenderBean.getTenderStatusId()));
		entity.setTenderedRate(tenderBean.getTenderedRate());
		entity.setWork(new Work(tenderBean.getWorkId()));
		entity.setTenderedRateSign(tenderBean.getTenderedRateSign());
	}

	private void convertContractorDepositBeanToContractorDepositEntityEntity(ContractorDeposit contractorDeposit,
			ContractorDepositBean contractorDepositBean) throws RESBusinessException {
		contractorDeposit.setAmount(contractorDepositBean.getAmount());
		contractorDeposit.setDepositeCategoryId(new DepositeCategory(contractorDepositBean.getDepositCategoryId()));
		contractorDeposit.setDepositeTypeId(new DepositeType(contractorDepositBean.getDepositTypeId()));
		contractorDeposit.setExpiredOn(RESUtil.convertStringToDate(contractorDepositBean.getExpiredOn()));
		contractorDeposit.setInstrumentNumber(contractorDepositBean.getInstrumentNumber());
		contractorDeposit.setInstrumentDate(RESUtil.convertStringToDate(contractorDepositBean.getInstrumentDate()));

		if (null != contractorDepositBean.getBankId()) {
			contractorDeposit.setBankId(new Bank(contractorDepositBean.getBankId()));
		}

	}

