	// Rakesh working
	@Override
	public WorkJson getAllWorkTender(Pageable pageable, String searchBoxVal, Long workType, Long workSubType,
			String loggedInUserRole, String username) {
		WorkJson adminSanctionJson = null;

		if (StringUtils.isEmpty(searchBoxVal)) {
			searchBoxVal = null;
		}
		Users userEntity = userRepository.findByUsernameAndStatus(username, RESConstants.STATUS_ACTIVE);
		List<Object[]> entityList = null;
		try {
//			Page<Work> adminSanction = workRepository
//					.findWorkTender(pageable, userEntity.getOffice().getId());

			int maxLimit = (pageable.getPageSize() * pageable.getPageNumber()) == 0 ? pageable.getPageSize()
					: (pageable.getPageSize() * pageable.getPageNumber());
			// long count = workRepository.countWorkTender();

			// if (adminSanction != null) {
			// List<Work> entityList = adminSanction.getContent();
			if (!loggedInUserRole.equals(RESConstants.ROLE_EnC)) {
				entityList = workRepository.findWorkTenderByQuery(userEntity.getOffice().getId(), pageable.getOffset(),
						maxLimit);
			} else {
				entityList = workRepository.findWorkTenderByQueryEnc(pageable.getOffset(), maxLimit);
			}

			List<WorkBean> beanList = new ArrayList<>();
			if (entityList != null && !entityList.isEmpty()) {
				int index = pageable.getPageNumber() * pageable.getPageSize();
				for (Object[] objArr : entityList) {

//						AdministrationSanctionBean bean = convertAdministrationSanctionEntityToTenderBean(administrationSanctionEntity);
//					/	WorkBean bean1 = convertWorkEntityToBean(administrationSanctionEntity);

					WorkBean bean = new WorkBean();
					bean.setWorkRequisitionNo((String) objArr[1]);
					// bean.setWorkRequisitionDate(RESUtil.convertDateToString(entity.getCreatedDate()));
					// bean.setIsLegacy(entity.getIsLegacy());
					bean.setWorkId(Long.parseLong(objArr[0].toString()));
					bean.setWorkName((objArr[2].toString()));
					// bean.setWorkTypeId(Long.parseLong(objArr[3].toString()));
					bean.setAgencyName(objArr[4].toString());
					bean.setTenderCost((BigDecimal) objArr[5]);
					if (objArr[6] != null)
						bean.setContractorId(Long.parseLong(objArr[6].toString()));
					bean.setContractorName((String) objArr[7]);
					if (objArr[8] != null) {
						bean.setWorkStatus((String) objArr[8]);
					}
					// bean.setWorkTypeName(entity.getWorkTypeId().getWorkTypeNameE());

					bean.setLoggedInUserRole(loggedInUserRole);
					bean.setIndex(++index);

					// WorkTender workTender =
					// workTenderRepository.findByWork(administrationSanctionEntity);
					// if (null != workTender) {
					bean.setTenderStatus((String) objArr[10]);
					if (objArr[9] != null)
						bean.setTenderStatusId(Long.parseLong(objArr[9].toString()));
					bean.setTenderCost((BigDecimal) objArr[5]);
					bean.setBidderName((String) objArr[7]);
					if (objArr[11] != null) {
						bean.setTenderParentId(Long.parseLong(objArr[11].toString()));
					}
					// }

					if (objArr[12] != null) {
						bean.setAdministrationSanctionId(Long.parseLong(objArr[12].toString()));
					}
					if (objArr[13] != null) {
						bean.setAdministrationSanctionTypeId(Long.parseLong(objArr[13].toString()));
					}
					if (objArr[14] != null) {
						bean.setWorkRequestStatusId(Long.parseLong(objArr[14].toString()));
					}
					beanList.add(bean);
				}
			}
			adminSanctionJson = new WorkJson();
			if (!loggedInUserRole.equals(RESConstants.ROLE_EnC)) {

				adminSanctionJson.setiTotalDisplayRecords(
						workRepository.findWorkTenderByQueryCount(userEntity.getOffice().getId()));
				adminSanctionJson
						.setiTotalRecords(workRepository.findWorkTenderByQueryCount(userEntity.getOffice().getId()));
			} else {
				adminSanctionJson.setiTotalDisplayRecords(workRepository.findWorkTenderByQueryCountEE());
				adminSanctionJson.setiTotalRecords(workRepository.findWorkTenderByQueryCountEE());
			}
			adminSanctionJson.setAaData(beanList);
			// }

			return adminSanctionJson;
		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return adminSanctionJson;
		}
	}

