	@Override
	public WorkTenderJson getAllWorkTenderList(Pageable pageable, String searchBoxVal, Long workType, Long workSubType,
			String loggedInUserRole, String username) {
		WorkTenderJson workTenderJson = null;

		if (StringUtils.isEmpty(searchBoxVal)) {
			searchBoxVal = null;
		}

		try {
			Page<WorkTender> workTender = workTenderRepository.findAll(pageable);

			long count = workTenderRepository.countWorkTenderList();

			if (workTender != null) {
				List<WorkTender> entityList = workTender.getContent();
				List<WorkTenderBean> beanList = new ArrayList<>();
				if (entityList != null && !entityList.isEmpty()) {
					int index = pageable.getPageNumber() * pageable.getPageSize();
					for (WorkTender element : entityList) {
						WorkTenderBean bean = convertWorkTenderEntityToTenderBean(element);
						bean.setLoggedInUserRole(loggedInUserRole);
						bean.setIndex(++index);
						beanList.add(bean);
					}
				}
				workTenderJson = new WorkTenderJson();
				workTenderJson.setiTotalDisplayRecords(workTender.getTotalElements());
				workTenderJson.setiTotalRecords(count);
				workTenderJson.setAaData(beanList);
			}
			return workTenderJson;
		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return workTenderJson;
		}
	}

