	@Override
	public void changeTechnicalSanctionStatus(String estimationId, Users user) {

		Long estimatedId = new Long(Long.parseLong(estimationId));
		WorkEstimation workEstimation = workEstimationRepository.findOne(estimatedId);
		TechnicalSanction technicalSanction = null;

		technicalSanction = technicalSanctionRepository
				.findByWorkEstimateId(new WorkEstimation(workEstimation.getId()));
		if (technicalSanction != null) {
			technicalSanction.setWorkEstimation(new WorkEstimation(workEstimation.getId()));
			technicalSanction.setTechnicalStatus(new TechnicalStatus((long) 1));

		} else {

			/*
			 * UUID uuid = UUID.randomUUID(); String generatedString =
			 * uuid.toString().substring(0, 8); generatedString = generatedString+"_ts_no";
			 */

			// 18-19/BPL/RC/1

			String financialYear = RESUtil.getFinancialYear();

			String generatedString = "";
			Work work = workEstimation.getWork();

			// Use work's executiveEngineerOffice instead of user's office (avoids NPE for SDO role)
			String officeName = (work.getExecutiveEngineerOffice() != null)
					? work.getExecutiveEngineerOffice().getOfficeName()
					: (user.getOffice() != null ? user.getOffice().getOfficeName() : "UNKNOWN");

			String office = officeName.substring(officeName.lastIndexOf(",") + 1);

			if (work.getAgencyTypeId().getAgencyTypeId() == 1) {
				generatedString = financialYear + "/" + office + "/" + "RC";

			} else if (work.getAgencyTypeId().getAgencyTypeId() == 2) {
				generatedString = financialYear + "/" + office + "/" + "GP";

			} else if (work.getAgencyTypeId().getAgencyTypeId() == 3) {
				generatedString = financialYear + "/" + office + "/" + "RD";
			}

			TechnicalSanctionNoGeneration technicalSanctionNoGeneration = technicalSanctionNoGenerationRepository
					.findByOfficeAndFinancialYear(office, financialYear);

			if (technicalSanctionNoGeneration == null) {
				generatedString = generatedString + "/1";
				persistTechnicalSanctionNoGeneration(financialYear, office, 1);
			} else {
				int newCount = technicalSanctionNoGeneration.getCounter() + 1;
				technicalSanctionNoGeneration.setCounter(newCount);
				technicalSanctionNoGenerationRepository.save(technicalSanctionNoGeneration);
				generatedString = generatedString + "/" + newCount;
			}

			technicalSanction = new TechnicalSanction();
			technicalSanction.setWork(new Work(workEstimation.getWork().getId()));
			technicalSanction.setWorkEstimation(new WorkEstimation(workEstimation.getId()));
			technicalSanction.setTechnicalStatus(new TechnicalStatus((long) 1));

			technicalSanction.setTechnicalSanctionNo(generatedString);

			technicalSanction.setTechnicalSanctionDate(new Date());

			List<TechnicalSanction> findAllTSByWork = technicalSanctionRepository.findAllTSByWork(work);
			if (null != findAllTSByWork && findAllTSByWork.size() > 0) {
				TechnicalSanction latestTS = (TechnicalSanction) findAllTSByWork.get(0);
				if (null != latestTS) {
					// if(null!=latestTS &&
					// latestTS.getTechnicalStatus().getId()==RESConstants.TS_STATUS_DISPATCHED) {
					technicalSanction
							.setTechnicalSanctionType(new TechnicalSanctionType(RESConstants.TS_TYPE_STATUS_REVISED));
				} else {
					technicalSanction
							.setTechnicalSanctionType(new TechnicalSanctionType(RESConstants.TS_TYPE_STATUS_ORIGINAL));
				}
				technicalSanction.setParentId(latestTS);
			}
		}

		technicalSanctionRepository.save(technicalSanction);

	}

	private void persistTechnicalSanctionNoGeneration(String financialYear, String office, int i) {

		TechnicalSanctionNoGeneration workLegacyIdGeneration = new TechnicalSanctionNoGeneration();
		workLegacyIdGeneration.setFinancialYear(financialYear);
		workLegacyIdGeneration.setOffice(office);
		workLegacyIdGeneration.setCounter(i);
		technicalSanctionNoGenerationRepository.save(workLegacyIdGeneration);

	}

