	@Override
	public String addTechnicalSanction(WorkBean workBean) {

		try {
			Work entity = workRepository.findOne(workBean.getWorkId());
			TechnicalSanction technicalSanctionEntity = technicalSanctionRepository
					.findByWorkEstimateId(new WorkEstimation(workBean.getWorkEstimateId()));
			// Rakesh for Null pointer check
			if (null != technicalSanctionEntity)
				technicalSanctionEntity.setWork(entity);
			else
				technicalSanctionEntity = new TechnicalSanction();

			TechnicalSanctionBean technicalSanctionBean = workBean.getTechnicalSanctionBean();

			if (technicalSanctionBean.getTechnicalSanctionFile() != null) {
				DocumentUpload documentUpload = RESUtil.uploadTsWorkDocument(
						documentRootPath + workTechSanctionDocumentPath, "blank",
						technicalSanctionBean.getTechnicalSanctionFile(), null, "blank");
				documentRepository.save(documentUpload);
				technicalSanctionEntity.setDocumentUploadTechnical(documentUpload);
				// legalDao.saveOrUpdate(legalDocumentUpload);
				// legalCaseHearing.setLegalDocumentUpload(new
				// LegalDocumentUpload(
				// legalDocumentUpload.getDocumentId()));
			}

			convertTechnicalSanctionBeanToEntity(technicalSanctionEntity, technicalSanctionBean);
			technicalSanctionRepository.save(technicalSanctionEntity);

			/*
			 * if(technicalSanctionBean.getTechnicalSanctionStatusId()==3) {
			 */
			if (null != technicalSanctionEntity.getTechnicalStatus()
					&& RESConstants.TS_STATUS_DISPATCHED.equals(technicalSanctionEntity.getTechnicalStatus().getId())) {
				if (RESConstants.TS_TYPE_STATUS_ORIGINAL
						.equals(technicalSanctionEntity.getTechnicalSanctionType().getTechnicalSanctionTypeId())) {
					entity.setWorkRequestStatusId(
							new RequestStatus(RESConstants.REQUEST_TS_GENERATED_AND_FORWARD_FOR_AS));
				} else if (RESConstants.TS_TYPE_STATUS_REVISED
						.equals(technicalSanctionEntity.getTechnicalSanctionType().getTechnicalSanctionTypeId())) {
					AdministrationSanction asPrevious = administrationSanctionRepository
							.findByTechnicalSanctionId(technicalSanctionEntity.getParentId());
					if (asPrevious != null) {
						BigDecimal asPreviousAmt = asPrevious.getAdministrativeSanctionAmount();
						if (technicalSanctionEntity.getTechnicalSanctionAmount().compareTo(asPreviousAmt) <= 0) {
							entity.setWorkRequestStatusId(new RequestStatus(
									RESConstants.REQUEST_STATUS_WORK_AGREEMENT_DONE_FWD_FOR_BILLING_INSPECTION_ID));
						} else {
							entity.setWorkRequestStatusId(
									new RequestStatus(RESConstants.REQUEST_TS_GENERATED_AND_FORWARD_FOR_AS));
						}
					}
				}
				entity.setModifiedDate(new Date());
				entity.setModifiedBy(RESUtil.getUserDetail().getUsername());
				workRepository.save(entity);
			}

			// }

			return null;

		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return RESConstants.ERROR_SAVING_DATA;
		}

	}

	@Override
//	@Transactional(rollbackFor = Exception.class)
	public String addAdminSanction(WorkBean workBean) {
		try {
			Work entity = workRepository.findOne(workBean.getWorkId());
			TechnicalSanction technicalSanction = technicalSanctionRepository
					.findOne(workBean.getTechnicalSanctionId());
			AdministrationSanction administrationSanctionEntity = null;
			AdministrationSanction administrationSanctionEntity2 = null;
			administrationSanctionEntity = administrationSanctionRepository
					.findByTechnicalSanctionId(new TechnicalSanction(workBean.getTechnicalSanctionId()));
//			administrationSanctionEntity  = administrationSanctionRepository.findByWork(new Work(workBean.getWorkId()));
//					technicalSanctionRepository.findByWorkEstimateId(new WorkEstimation(workBean.getWorkEstimateId()));
			if (administrationSanctionEntity != null) {
				// edit
				if (workBean.getAdministrationSanctionFile() != null) {
					DocumentUpload documentUpload = RESUtil.uploadAsWorkDocument(
							documentRootPath + workAdminSanctionDocumentPath, "blank",
							workBean.getAdministrationSanctionFile(), null, "blank");
					documentRepository.save(documentUpload);
					administrationSanctionEntity.setDocumentUpload(documentUpload);

				}

				convertWorkBeanToAdministrationSanctionEntity(administrationSanctionEntity, workBean);

				administrationSanctionEntity.setTechnicalSanction(new TechnicalSanction(technicalSanction.getId()));

				if (null == administrationSanctionEntity.getAdministrativeStatus()
						&& technicalSanction.getTechnicalSanctionType() != null) {
					administrationSanctionEntity.setAdministrationSanctionType(new AdministrationSanctionType(
							technicalSanction.getTechnicalSanctionType().getTechnicalSanctionTypeId()));
				}

				/*
				 * administrationSanctionEntity2 =
				 * administrationSanctionRepository.findByWork(new Work(workBean.getWorkId()));
				 */
				administrationSanctionEntity2 = administrationSanctionRepository.findAllASByWork(entity).get(0);

				administrationSanctionEntity.setWork(new Work(workBean.getWorkId()));

				if (workBean.getAdministrationSanctionStatusId() == 2) { // submit

					if (RESConstants.AS_TYPE_STATUS_ORIGINAL.equals(administrationSanctionEntity
							.getAdministrationSanctionType().getAdministrationSanctionTypeId())) {
						// GP & Vibhagiya
						if (entity.getAgencyTypeId().getAgencyTypeId().equals(RESConstants.AGENCY_TYPE_GP) || entity
								.getAgencyTypeId().getAgencyTypeId().equals(RESConstants.AGENCY_TYPE_VIBHAGIYA)) {
							// if(entity.getAgencyTypeId().getAgencyTypeId() == RESConstants.AGENCY_TYPE_GP)
							// {
							entity.setWorkRequestStatusId(new RequestStatus(
									RESConstants.REQUEST_STATUS_WORK_AGREEMENT_DONE_FWD_FOR_BILLING_INSPECTION_ID));
							entity.setWorkStatusId(new WorkStatus(RESConstants.STATUS_IN_PROGRESS_ID));
						} else {
							entity.setWorkRequestStatusId(new RequestStatus(
									RESConstants.REQUEST_STATUS_AS_RECEIVED_AND_FWD_FOR_WORK_ORDERTENDER_DETAILS));
						}
					} else if (RESConstants.AS_TYPE_STATUS_REVISED.equals(administrationSanctionEntity
							.getAdministrationSanctionType().getAdministrationSanctionTypeId())) {
						entity.setWorkRequestStatusId(new RequestStatus(
								RESConstants.REQUEST_STATUS_WORK_AGREEMENT_DONE_FWD_FOR_BILLING_INSPECTION_ID));
					}

					// entity.setWorkRequestStatusId(new
					// RequestStatus(RESConstants.REQUEST_STATUS_AS_RECEIVED_AND_FWD_FOR_WORK_ORDERTENDER_DETAILS));

					/*
					 * if(entity.getAgencyTypeId().getAgencyTypeId() == RESConstants.AGENCY_TYPE_GP
					 * || entity.getAgencyTypeId().getAgencyTypeId() ==
					 * RESConstants.AGENCY_TYPE_VIBHAGIYA) { entity.setWorkStatusId(new
					 * WorkStatus(RESConstants.STATUS_IN_PROGRESS_ID)); }
					 */

					if (technicalSanction.getTechnicalSanctionType().getTechnicalSanctionTypeId() == 1) { // Original
						// entity.setFinancialYear(RESUtil.getFinacialYearString(administrationSanctionEntity.getAdministrativeSanctionDate()));
						entity.setFinancialYear(RESUtil
								.getFinacialYearFromDate(administrationSanctionEntity.getAdministrativeSanctionDate()));
					}
					entity.setModifiedDate(new Date());
					entity.setModifiedBy(RESUtil.getUserDetail().getUsername());
					workRepository.save(entity);
				}
				// Rakesh
				// List<Admistar> findAllTSByWork =
				// administrationSanctionRepository.findAllASByWork(work);
				if (null != administrationSanctionEntity2
						&& !administrationSanctionEntity2.getId().equals(administrationSanctionEntity.getId())) {
					// TechnicalSanction latestTS=(TechnicalSanction)findAllTSByWork.get(0);
					/*
					 * technicalSanction.setTechnicalSanctionType(new
					 * TechnicalSanctionType(RESConstants.TS_TYPE_STATUS_REVISED)); if(null!=
					 * technicalSanction) {
					 */
					administrationSanctionEntity.setParentId(administrationSanctionEntity2);
					// }
				}
				//
				administrationSanctionRepository.save(administrationSanctionEntity);

			} else {
				// new

				administrationSanctionEntity = new AdministrationSanction();
				administrationSanctionEntity.setWork(new Work(workBean.getWorkId()));

				if (workBean.getAdministrationSanctionFile() != null) {
					DocumentUpload documentUpload = RESUtil.uploadAsWorkDocument(
							documentRootPath + workAdminSanctionDocumentPath, "blank",
							workBean.getAdministrationSanctionFile(), null, "blank");
					documentRepository.save(documentUpload);
					administrationSanctionEntity.setDocumentUpload(documentUpload);

				}

				convertWorkBeanToAdministrationSanctionEntity(administrationSanctionEntity, workBean);
				administrationSanctionEntity.setTechnicalSanction(new TechnicalSanction(technicalSanction.getId()));

				/*
				 * if (technicalSanction.getTechnicalSanctionType()!= null) {
				 * administrationSanctionEntity.setAdministrationSanctionType(new
				 * AdministrationSanctionType(technicalSanction.getTechnicalSanctionType().
				 * getTechnicalSanctionTypeId())); }
				 */

				/*
				 * administrationSanctionEntity2 =
				 * administrationSanctionRepository.findByWork(new Work(workBean.getWorkId()));
				 */
				administrationSanctionEntity2 = administrationSanctionRepository.findAllASByWork(entity).size() > 0
						? administrationSanctionRepository.findAllASByWork(entity).get(0)
						: null;

				if (administrationSanctionEntity2 == null) {
					administrationSanctionEntity.setWork(new Work(workBean.getWorkId()));
					administrationSanctionEntity.setAdministrationSanctionType(
							new AdministrationSanctionType(RESConstants.AS_TYPE_STATUS_ORIGINAL));

				} else {
					// Rakesh code
					administrationSanctionEntity.setParentId(administrationSanctionEntity2);
					// if(administrationSanctionEntity.getAdministrativeStatus().getId() >
					// RESConstants.STATUS_SAVE_AS_DRAFT_ID) {
					administrationSanctionEntity.setAdministrationSanctionType(
							new AdministrationSanctionType(RESConstants.AS_TYPE_STATUS_REVISED));
					// }
					/*
					 * else { administrationSanctionEntity.setAdministrationSanctionType(new
					 * AdministrationSanctionType(RESConstants.AS_TYPE_STATUS_ORIGINAL)); }
					 */
				}
				if (workBean.getAdministrationSanctionStatusId() == 2) { // submit

					if (RESConstants.AS_TYPE_STATUS_ORIGINAL.equals(administrationSanctionEntity
							.getAdministrationSanctionType().getAdministrationSanctionTypeId())) {
						// GP & Vibhagiya
						if (entity.getAgencyTypeId().getAgencyTypeId().equals(RESConstants.AGENCY_TYPE_GP) || entity
								.getAgencyTypeId().getAgencyTypeId().equals(RESConstants.AGENCY_TYPE_VIBHAGIYA)) {
							// if(entity.getAgencyTypeId().getAgencyTypeId() == RESConstants.AGENCY_TYPE_GP)
							// {
							entity.setWorkRequestStatusId(new RequestStatus(
									RESConstants.REQUEST_STATUS_WORK_AGREEMENT_DONE_FWD_FOR_BILLING_INSPECTION_ID));
							entity.setWorkStatusId(new WorkStatus(RESConstants.STATUS_IN_PROGRESS_ID));
						} else {
							entity.setWorkRequestStatusId(new RequestStatus(
									RESConstants.REQUEST_STATUS_AS_RECEIVED_AND_FWD_FOR_WORK_ORDERTENDER_DETAILS));
						}
					} else if (RESConstants.AS_TYPE_STATUS_REVISED.equals(administrationSanctionEntity
							.getAdministrationSanctionType().getAdministrationSanctionTypeId())) {
						entity.setWorkRequestStatusId(new RequestStatus(
								RESConstants.REQUEST_STATUS_WORK_AGREEMENT_DONE_FWD_FOR_BILLING_INSPECTION_ID));
					}

					if (technicalSanction.getTechnicalSanctionType().getTechnicalSanctionTypeId() == 1) { // Original
						entity.setFinancialYear(RESUtil
								.getFinacialYearString(administrationSanctionEntity.getAdministrativeSanctionDate()));
					}
					entity.setModifiedDate(new Date());
					entity.setModifiedBy(RESUtil.getUserDetail().getUsername());
					workRepository.save(entity);
				}

				administrationSanctionRepository.save(administrationSanctionEntity);

			}

			return null;
		} catch (Exception e) {
			logger.error(e.getMessage());
			e.printStackTrace();
			return RESConstants.ERROR_SAVING_DATA;
		}
	}

	private void convertWorkBeanToAdministrationSanctionEntity(AdministrationSanction administrationSanctionEntity,
			WorkBean workBean) throws RESBusinessException {

		administrationSanctionEntity.setCompetentAuthDesig(workBean.getCompetentAuthDesig());
		administrationSanctionEntity.setCompetentAuthName(workBean.getCompetentAuthName());

		administrationSanctionEntity.setAdministrativeSanctionNo(workBean.getAdministrationSanctionNo());
		administrationSanctionEntity.setProposeddistance(workBean.getProposeddistance());

		administrationSanctionEntity
				.setAdministrativeSanctionDate(RESUtil.convertStringToDate(workBean.getAdministrationSanctionDate()));

		if (workBean.getIssuingAuthorityId() != null) {
			administrationSanctionEntity.setIssuingAuthority(new IssuingAuthority(workBean.getIssuingAuthorityId()));
		}

		administrationSanctionEntity.setAdministrativeSanctionAmount(workBean.getTotalCost());

		administrationSanctionEntity.setStatus(RESConstants.STATUS_ACTIVE);
		administrationSanctionEntity
				.setAdministrativeStatus(new AdministrativeStatus(workBean.getAdministrationSanctionStatusId()));
		administrationSanctionEntity.setContingencyAmount(workBean.getContingencyAmount());

	}

