	public CCDetailsBean fetchInitiatedCCByWork(Long workId) {
		CCDetailsBean ccDetailsBean = null;
		// CCDetails ccDetails = ccDetailsRepository.findByWork(new Work(workId));
		CCDetails ccDetails = ccDetailsRepository.findByWorkOrderByCreatedDateDesc(new Work(workId)).size() > 0
				? ccDetailsRepository.findByWorkOrderByCreatedDateDesc(new Work(workId)).get(0)
				: null;
		if (ccDetails != null) {
			ccDetailsBean = new CCDetailsBean();
			ccDetailsBean.setWorkCompletedOn(RESUtil.convertDateToString(ccDetails.getWorkCompletedOn()));
			ccDetailsBean.setTakenOverOn(RESUtil.convertDateToString(ccDetails.getTakenOverOn()));
			ccDetailsBean.setCcInitiatedOn(RESUtil.convertDateToString(ccDetails.getCreatedDate()));
			ccDetailsBean.setApproved(ccDetails.getApproved());
			if (ccDetails.getApproved() == null) {
				ccDetailsBean.setStatus("Inspection In-Progress");
			} else if (ccDetails.getApproved() == false) {
				ccDetailsBean.setStatus("CC Request Rejected");
			} else if (ccDetails.getApproved() == true) {
				ccDetailsBean.setStatus("Forwarded for Physical CC");
			}
		}
		return ccDetailsBean;
	}

