	public WorkJson fetchGeneralInspectionList(Pageable pageable, String searchBoxVal, String loggedInUserRole,
			String username) {

		Users entity = userRepository.findByUsernameAndStatus(username, RESConstants.STATUS_ACTIVE);
		Page<Work> work = workRepository.fetchWorkForGeneralInspectionListforEE(pageable, entity.getOffice());
		long totalCount = workRepository.countWorkGeneralInspectionListforEE(entity.getOffice());

//		long count = 0;
		WorkJson workJson = null;
		if (work != null) {
			List<Work> entityList = work.getContent();
			List<WorkBean> beanList = new ArrayList<>();
			if (entityList != null && !entityList.isEmpty()) {

				int index = pageable.getPageNumber() * pageable.getPageSize();
				for (Work element : entityList) {

					List<InspectionDetails> inspectionList = inspectionDetailsRepo
							.findByWorkIdAndGeneralInspectionDone(element.getId(), (short) 1);

					// List<InspectionAnswersNew> list =
					// inspectionAnswerRepositoryNew.findByInspection(inspection);
					if (inspectionList != null && inspectionList.size() > 0) {
						WorkBean bean = convertWorkEntityToBean(element);
						/*
						 * if (c != null) { bean.setCcInitiatedBy(c.getCreatedBy());
						 * bean.setCcInitiatedOn(RESUtil.convertDateToString(c.getCreatedDate())); }
						 */

						bean.setLoggedInUserRole(loggedInUserRole);
						bean.setIndex(++index);
						beanList.add(bean);
					}
				}
			}

			workJson = new WorkJson();
			workJson.setiTotalDisplayRecords(work.getTotalElements());
			workJson.setiTotalRecords(totalCount);
			workJson.setAaData(beanList);
		}

		return workJson;
	}

