	public List<BillDataInspectionBean> fetchCCInspectionPendingWorks(String username, Long status, String role) {

		WorkBean workBean = null;

		Users entity = userRepository.findByUsernameAndStatus(username, RESConstants.STATUS_ACTIVE);

		List<BillDataInspectionBean> list = new ArrayList<BillDataInspectionBean>();

		// Only OIC can get Work for inspection
		if (RESConstants.ROLE_EE.equals(role) && entity.getIsOIC() != null && entity.getIsOIC() == 1) {

			List<Work> workList = workRepository.fetchCCInspectionPendingWorks(entity.getOffice());

			BillDataInspectionBean billDataInspectionBean = null;

			for (Work work : workList) {

				workBean = convertWorkEntityToBean(work);

				billDataInspectionBean = convertWorkBeantoBillInspectionBean(workBean);

				if (workBean.getWorkId() != null) {
					// CCDetails cc=ccDetailsRepository.findByWork(new Work(workBean.getWorkId()));
					CCDetails cc = ccDetailsRepository.findByWorkOrderByCreatedDateDesc(new Work(workBean.getWorkId()))
							.size() > 0
									? ccDetailsRepository
											.findByWorkOrderByCreatedDateDesc(new Work(workBean.getWorkId())).get(0)
									: null;
					if (cc != null) {
						if (cc.getCcInspectionSubmittedOn() != null) {
							billDataInspectionBean.setInspectionUploadedDate(
									RESUtil.convertDateToString(cc.getCcInspectionSubmittedOn()));
						}
					}
				}

				list.add(billDataInspectionBean);

			}
		}

		return list;

	}

