	public List<InspectionAnswerCC> fetchInspectionAswerByWorkId(Long WorkId) {

		List<InspectionAnswerCC> list = inspectionAnswerRepositoryCC.findByWork(new Work(WorkId));
		for (InspectionAnswerCC inspectionAnswer : list) {
			inspectionAnswer.setWork(null);
			inspectionAnswer.setAnswerBy(null);
		}
		return list;
	}

	public List<InspectionAnswerImageCC> fetchInspectionAswerImageCCByWorkId(Long workId) {

		List<InspectionAnswerImageCC> list = inspectionAnswerImageRepositoryCC.findByWork(new Work(workId));

		for (InspectionAnswerImageCC image : list) {
			image.setWork(null);
			image.setImageBy(null);
		}
		return list;
	}

	public void updateWorkStatus(Long workId, Long status) {
		Work work = workRepository.findOne(workId);
		work.setWorkRequestStatusId(new RequestStatus(status));
		workRepository.saveAndFlush(work);
	}

	public WorkJson fetchWorkListForCC(Pageable pageable, String role, Long officeId, Long userId)
			throws RESBusinessException {

		WorkJson workJson = null;
		Page<Work> works = null;
		works = workRepository.fetchWorkListForCC(pageable, officeId);
		long count = workRepository.countWorkListForCC(officeId);

		if (works != null) {
			List<Work> entityList = works.getContent();
			List<WorkBean> beanList = new ArrayList<>();
			if (entityList != null && !entityList.isEmpty()) {

				int index = pageable.getPageNumber() * pageable.getPageSize();
				for (Work work : entityList) {

					WorkBean bean = convertWorkEntityToBeanDuringListing(work); // convert
					bean.setIndex(++index);
					beanList.add(bean);
				}
			}
			workJson = new WorkJson();
			workJson.setAaData(beanList);
			workJson.setiTotalDisplayRecords(works.getTotalElements());
			workJson.setiTotalRecords(count);
		}
		return workJson;

	}

	@Override
	public DeductionBean fetchBillDeduction(Long workId) {

		DeductionBean deductionBean = new DeductionBean();

		try {
			List<Bill> billEntityList = billRepository.findByWorkAndStatusStatusIdNotIn(new Work(workId),
					RESConstants.STATUS_FINAL_BILL_REJECTED_ID);

			BigDecimal totalSecurityDeposit = new BigDecimal(0);
			BigDecimal totalIncomeTax = new BigDecimal(0);
			BigDecimal totalUpkar = new BigDecimal(0);
			BigDecimal totalRoyalty = new BigDecimal(0);
			BigDecimal totalOther = new BigDecimal(0);
			BigDecimal totalMiscDeposit = new BigDecimal(0);
			BigDecimal totalPerformanceGuarantee = new BigDecimal(0);
			BigDecimal totalAdvancePayments = new BigDecimal(0);
			BigDecimal totalCostOfBillForm = new BigDecimal(0);

			for (Bill billEntity : billEntityList) {

				totalSecurityDeposit = totalSecurityDeposit.add(
						billEntity.getSecurityDeposit() != null ? billEntity.getSecurityDeposit() : BigDecimal.ZERO);
				totalIncomeTax = totalIncomeTax
						.add(billEntity.getIncomeTax() != null ? billEntity.getIncomeTax() : BigDecimal.ZERO);
				totalUpkar = totalUpkar.add(billEntity.getUpkar() != null ? billEntity.getUpkar() : BigDecimal.ZERO);
				totalRoyalty = totalRoyalty
						.add(billEntity.getRoyalty() != null ? billEntity.getRoyalty() : BigDecimal.ZERO);
				totalOther = totalOther.add(billEntity.getOther() != null ? billEntity.getOther() : BigDecimal.ZERO);
				totalMiscDeposit = totalMiscDeposit
						.add(billEntity.getMiscDeposit() != null ? billEntity.getMiscDeposit() : BigDecimal.ZERO);
				totalPerformanceGuarantee = totalPerformanceGuarantee
						.add(billEntity.getPerformanceGuarantee() != null ? billEntity.getPerformanceGuarantee()
								: BigDecimal.ZERO);
				totalAdvancePayments = totalAdvancePayments.add(
						billEntity.getAdvancePayments() != null ? billEntity.getAdvancePayments() : BigDecimal.ZERO);
				totalCostOfBillForm = totalCostOfBillForm
						.add(billEntity.getCostOfBillForm() != null ? billEntity.getCostOfBillForm() : BigDecimal.ZERO);
			}

			deductionBean.setTotalAdvancePayments(totalAdvancePayments);
			deductionBean.setTotalCostOfBillForm(totalCostOfBillForm);
			deductionBean.setTotalIncomeTax(totalIncomeTax);
			deductionBean.setTotalMiscDeposit(totalMiscDeposit);
			deductionBean.setTotalOther(totalOther);
			deductionBean.setTotalPerformanceGuarantee(totalPerformanceGuarantee);
			deductionBean.setTotalRoyalty(totalRoyalty);
			deductionBean.setTotalSecurityDeposit(totalSecurityDeposit);
			deductionBean.setTotalUpkar(totalUpkar);

		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return null;
		}
		return deductionBean;
	}

	@Override
	public List<BillBean> fetchBillListForWork(Long workId) {

		List<BillBean> billBeanList = new LinkedList<BillBean>();
		try {
			List<Bill> billEntityList = new LinkedList<Bill>();
			if (null != workId) {
				billEntityList = billRepository.findByWorkAndStatusStatusIdNotIn(new Work(workId),
						Arrays.asList(RESConstants.STATUS_DELETED_ID, RESConstants.STATUS_FINAL_BILL_REJECTED_ID,
								RESConstants.STATUS_SAVE_AS_DRAFT_ID));
				for (Bill billEntity : billEntityList) {
					BillBean billBean = convertBillEntityToBean(billEntity);

					List<InspectionAnswer> list = inspectionAnswerRepository.findByBillAndCode(billEntity,
							"PhysicalStage");
					if (null != list && !list.isEmpty()) {
						InspectionAnswer ia = list.get(0);
						billBean.setInspectionPhysicalStage(ia.getAnswer());
					}

					List<PaymentTable> paymentTableList = paymentRepository.findByBill(billEntity);
					if (paymentTableList != null && !paymentTableList.isEmpty()) {
						BigDecimal paidAmount = new BigDecimal(0);
						for (PaymentTable paymentTable : paymentTableList) {
							List<PaymentDetail> paymentDetailList = paymentDetailRepository
									.findByPaymentTable(paymentTable);
							for (PaymentDetail paymentDetail : paymentDetailList) {
								if (null != paymentDetail.getAmount()) {
									paidAmount = paidAmount.add(paymentDetail.getAmount());
								}
								if (paymentDetail.getInstrumentDate() != null) {
									billBean.setPaidDate(paymentDetail.getInstrumentDate());
								}

							}
							billBean.setPaidAmount(paidAmount);

						}

					}

					billBeanList.add(billBean);
				}
			} else {
				billEntityList = billRepository.findByStatusStatusIdNotIn(Arrays.asList(RESConstants.STATUS_DELETED_ID,
						RESConstants.STATUS_FINAL_BILL_REJECTED_ID, RESConstants.STATUS_SAVE_AS_DRAFT_ID));
				for (Bill billEntity : billEntityList) {
					BillBean billBean = convertBillEntityToBeanForWS(billEntity);

					List<InspectionAnswer> list = inspectionAnswerRepository.findByBillAndCode(billEntity,
							"PhysicalStage");
					if (null != list && !list.isEmpty()) {
						InspectionAnswer ia = list.get(0);
						billBean.setInspectionPhysicalStage(ia.getAnswer());
					}

					List<PaymentTable> paymentTableList = paymentRepository.findByBill(billEntity);
					if (paymentTableList != null && !paymentTableList.isEmpty()) {
						BigDecimal paidAmount = new BigDecimal(0);
						for (PaymentTable paymentTable : paymentTableList) {
							List<PaymentDetail> paymentDetailList = paymentDetailRepository
									.findByPaymentTable(paymentTable);
							for (PaymentDetail paymentDetail : paymentDetailList) {
								if (null != paymentDetail.getAmount()) {
									paidAmount = paidAmount.add(paymentDetail.getAmount());
								}
								if (paymentDetail.getInstrumentDate() != null) {
									billBean.setPaidDate(paymentDetail.getInstrumentDate());
								}

							}
							billBean.setPaidAmount(paidAmount);

						}

					}

					billBeanList.add(billBean);
				}
			}

		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return null;
		}
		return billBeanList;
	}

