	public void updateFinancialYearForWorkForNonLegacyData() throws RESBusinessException {

		System.out.println("Started....updateFinancialYearForWorkForNonLegacyData.....");

		List<Work> workList = new ArrayList<Work>();
		List<AdministrationSanction> list = administrationSanctionRepository
				.findByAdministrationSanctionTypeAdministrationSanctionTypeIdForNonLegacyData(1L);
		System.out.println("total record found in DB : " + list.size());
		int i = 0;
		long start = System.currentTimeMillis();
		Work work = null;

		for (AdministrationSanction administrationSanction : list) {

			String fy = RESUtil.getFinacialYearFromDate(administrationSanction.getAdministrativeSanctionDate());
			work = administrationSanction.getWork();
			if (work != null) {
				work.setFinancialYear(fy);
//				System.out.println(work.getId() + "..." + work.getFinancialYear());
				workRepository.save(work);
				// workRepository.flush();
				workList.add(work);
				i++;
			}

		}

		workRepository.save(workList);

		System.out.println("total record found in DB : " + list.size());
		System.out.println("total record updated in DB: " + i);

		long elapsedTimeMillis = System.currentTimeMillis() - start;

		// Get elapsed time in minutes
		float elapsedTimeMin = elapsedTimeMillis / (60 * 1000F);
		System.out.println(elapsedTimeMin);
		System.out.println("Ended....updateFinancialYearForWorkForNonLegacyData.....");
		updateFinancialYearForWorkForNonLegacyDataLeft();

	}

