	@Override
	public String updateOfficer(WorkBean bean) {
		try {

			Work entity = workRepository.findOne(bean.getWorkId());

			// copy data into histroy table first....
			WorkOfficersHistory workOfficersHistoryEntity = new WorkOfficersHistory();
			workOfficersHistoryEntity.setWork(new Work(bean.getWorkId()));

			if (null != entity.getAssistantEngineer()) {
				workOfficersHistoryEntity.setAssistantEngineer(new Users(entity.getAssistantEngineer().getId()));
			}
			if (null != entity.getSubEngineer()) {
				workOfficersHistoryEntity.setSubEngineer(new Users(entity.getSubEngineer().getId()));
			}

			workOfficersHistoryRepository.saveAndFlush(workOfficersHistoryEntity);

			if (bean.getSubEngineerId() != null) {
				entity.setSubEngineer(new Users(bean.getSubEngineerId()));
			}

			if (bean.getAssistantEngineerId() != null) {
				entity.setAssistantEngineer(new Users(bean.getAssistantEngineerId()));
			}
			workRepository.save(entity);
			return null;

		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return RESConstants.ERROR_SAVING_DATA;
		}

	}

