	@Override
	public List<BillDataInspectionBean> fetchRandomInspectionPendingWorks(Long userId) {
		// TODO Auto-generated method stub
		List<BillDataInspectionBean> billDataInspectionBeans = new ArrayList<>();
		List<Long> listOfWorks = new ArrayList<>();
		List<Long> listOfOffices = new ArrayList<>();
		List<Object[]> objects = null;

		// SqmAllocation
		try {
			List<SqmAllocation> allocations = sqmAllocationRepository
					.findByUsersAndInspectionDoneAndEnabled(new Users(userId), (short) 0, (short) 1);

			for (Iterator iterator = allocations.iterator(); iterator.hasNext();) {
				SqmAllocation sqmAllocation = (SqmAllocation) iterator.next();
				if (sqmAllocation.getWork() != null) {
					listOfWorks.add(sqmAllocation.getWork().getId());
				}
				if (sqmAllocation.getOfficeId() != null) {
					listOfOffices.add(sqmAllocation.getOfficeId());
				}

			}
			if (!listOfWorks.isEmpty() && listOfWorks.size() > 0 && !listOfOffices.isEmpty()
					&& listOfOffices.size() > 0) {
				objects = workRepository.findBySqmWorkIdsOrExecutiveEnginerOfficeIds(listOfWorks, listOfOffices,
						userId);
			} else if (!listOfWorks.isEmpty() && listOfOffices.isEmpty()) {
				objects = workRepository.findBySqmWorkIds(listOfWorks);
			} else if (listOfWorks.isEmpty() && !listOfOffices.isEmpty()) {
				objects = workRepository.findBySqmOfficeIds(listOfOffices);
			}
			// workRepository.findAdminLegacyWorksByIsLegacy(isLegacy)

		} catch (Exception e) {
			e.printStackTrace();
		}
		if (objects != null) {
			for (Object[] object : objects) {
				BillDataInspectionBean bean = new BillDataInspectionBean();
				bean.setRandomAllocationId(Long.parseLong(object[19].toString()));
				if (object[20] != null)
					// bean.setSqmAllocationDate(object[20].toString());

					bean.setDistrictName(object[10].toString());
				bean.setId(Long.parseLong(object[0].toString()));
				bean.setWorkId(Long.parseLong(object[0].toString()));
				if (object[0] != null) {
					WorkTenderBean workTenderBean = fetchWorkTenderDetailsByWorkId(
							Long.parseLong(object[0].toString()));
					if (workTenderBean != null)
						bean.setPacAmount(workTenderBean.getAmountOfContract().toString());
				} else {
					bean.setPacAmount(null);
				}
				bean.setWorkName(object[2].toString());
				if (object[3] != null)
					bean.setWorkTypeId(Long.parseLong(object[3].toString()));
				if (object[1] != null)
					bean.setRegistrationNo(object[1].toString());

				bean.setWorkTypeName(object[4].toString());
				if (object[6] != null)
					bean.setWorksubTypeName(object[6].toString());
				bean.setLineDepartmentName(object[8].toString());
				// bean.setContractorName(object[7].toString());
				bean.setWorkStatus(object[12].toString());
				if (object[14] != null)
					bean.setContractorName(object[14].toString());
				if (object[15] != null)
					bean.setLatitude(object[15].toString());
				if (object[16] != null)
					bean.setLongitude(object[16].toString());
				billDataInspectionBeans.add(bean);
				// if (object[17] != null)
				// if (object[18] != null)
				// bean.setExecutiveEngineerOfficeName(object[18].toString());
				// bean.setExecutiveEngineerOfficeId(Long.parseLong(object[17].toString()));

				// setSqmURL(bean, Long.parseLong(object[3].toString()));

			}

		}
		return billDataInspectionBeans;
	}

