	@Override
	public String updateBillStatusRemarks(BillBean billBean, String userId) {
		try {
			Bill bill = billRepository.findOne(billBean.getId());

			/*
			 * if(workBean.getContractorId()!=null) { work.setContractor(new
			 * Contractor(workBean.getContractorId())); }else { work.setContractor(null); }
			 */
			bill.setStatus(new MasterBillStatus((long) 10));
			if (billBean.getBillRemark() != null) {
				bill.setBillRemark(billBean.getBillRemark());
			} else {
				bill.setBillRemark(null);
			}

			bill.setModifiedDate(new Date());
			bill.setModifiedBy(userId);
			billRepository.saveAndFlush(bill);
			return null;
		} catch (Exception e) {
			e.printStackTrace();
			logger.error("An exception occurred.", e);
			return RESConstants.ERROR_SAVING_DATA;
		}
	}

