	public List<UserBean> fetchUsersByDesig(Long desigId) {
		try {
			List<Users> user = userRepository.findByDesignationAndStatus(new Designation(desigId),
					RESConstants.STATUS_ACTIVE);
			if (user != null) {

				List<UserBean> beanList = new ArrayList<>();
				for (Users users : user) {
					beanList.add(convertUserEntityToBean(users));
				}
				return beanList;
			} else {
				return null;
			}
		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return null;
		}
	}

