	@Override
	public List<WorkBean> fetchAllWorkByOfficersEEOfficeId(String eeOfficeId) {
		List<WorkBean> beans = new ArrayList();
		if (eeOfficeId != null) {
			// String[] eeOfficeIds= eeOfficeId.split(",");
			List<Long> list = Arrays.stream(eeOfficeId.split(",")).map(Long::parseLong).collect(Collectors.toList());
			List<Object[]> objects = workRepository.findByExecutiveEnginerOfficeIds(list);

			for (Object[] obj : objects) {
				WorkBean bean = new WorkBean();
				bean.setWorkId(Long.parseLong(obj[0].toString()));
				bean.setWorkName(obj[1].toString());
				if (obj[2] != null) {
					bean.setExecutiveEngineerOfficeId(Long.parseLong(obj[2].toString()));
					// Office office=officeRepository.findById(Long.parseLong(obj[2].toString()));
					// bean.setExecutiveEngineerOfficeName(office.getOfficeName());
				}
				if (obj[3] != null)
					bean.setExecutiveEngineerOfficeName((String) obj[3]);
				// Load EE name and
				// bean.
				bean.setWorkTypeName((String) obj[4]);
				bean.setWorkRequisitionNo((String) obj[5]);
				/*
				 * List<SqmAllocationBean> allSqmAllocationsByWorkId =
				 * getAllSqmAllocationsByWorkId(bean.getWorkId());
				 */
				List<SqmAllocationBean> allSqmAllocationsByWorkId = getAllOfficersAllocationsByWorkId(bean.getWorkId());
				if (null != allSqmAllocationsByWorkId && allSqmAllocationsByWorkId.size() > 0) {
					bean.setSqmInspectionStatus("Inspection Done.");
				} else {
					bean.setSqmInspectionStatus("Inspection Pending.");
				}

				beans.add(bean);
			}
		}

		return beans;
	}

