	// Rakesh
	public void updateBillStatusForRunningAndFinalBillNew(Long billId, Long status, String role, String username,
			String remarks) {

		Bill bill = billRepository.findOne(billId);
		bill.setSubEnggRemark(remarks);
		// bill.setModifiedByAppUser(username);
		if (bill.getBillType().equals(RESConstants.BILL_TYPE_RUNNING)) {
			bill.setStatus(new MasterBillStatus(status));
		} else if (bill.getBillType().equals(RESConstants.BILL_TYPE_FINAL)) {
			if (RESConstants.ROLE_AE.equals(role)) {
				bill.setInspectedByDatetime(new Date());
				if (null != bill.getInspectedByEeDatetime()) {
					bill.setStatus(new MasterBillStatus(status));

				}

			} else if (RESConstants.ROLE_EE.equals(role)) {
				bill.setInspectedByEeDatetime(new Date());
				if (null != bill.getInspectedBySubEnggDatetime()) {
					bill.setStatus(new MasterBillStatus(status));
				}
			} else if (RESConstants.ROLE_SUB_ENGG.equals(role)) {
				bill.setInspectedBySubEnggDatetime(new Date());
				if (null != bill.getInspectedBySubEnggDatetime()) {
					bill.setStatus(new MasterBillStatus(status));
				}
			} else if (RESConstants.ROLE_SDO.equals(role)) {
				bill.setInspectedBySdoDatetime(new Date());
				if (null != bill.getInspectedBySubEnggDatetime()) {
					bill.setStatus(new MasterBillStatus(status));
				}
			}
		}
		billRepository.saveAndFlush(bill);
	}

	@Override
	public void addContractorsAsUsers() {
		List<Object[]> entityList = null;
		entityList = contractorRepository.findAllContractor();

		if (entityList != null && !entityList.isEmpty()) {
			for (Object[] objArr : entityList) {

				Users users = new Users();
				if (objArr[8] != null) {

					try {
						Users us = userRepository.findByEmailId((String) objArr[8]);
						if (us != null) {
							throw new RuntimeException("User Defined Exception For Duplicate Users");
						}

						users.setUsername((String) objArr[8]);
						users.setPassword((String) objArr[9]);
						users.setName((String) objArr[1]);
						users.setDesignation(new Designation((long) 8));

						users.setEmailId((String) objArr[8]);

						if (objArr[9] != null) {
							users.setMobileNo((String) objArr[9]);
						}
						users.setStatus("Active");
						users.setContractor(new Contractor(Long.parseLong(objArr[0].toString())));

						// set users into user_role table
						Set<Role> roles = new HashSet<>();
						roles.add(roleRepository.findOne(RESConstants.ROLE_CONTRACTOR));// support for one
						users.setRoles(roles);

						Users userObj = userRepository.save(users);
						System.out.println("contractor as users saved!");

						Contractor c = contractorRepository.findOne(Long.parseLong(objArr[0].toString()));
						c.setUserStatus((short) 1);
						contractorRepository.save(c);

						// message
						// email

						if (objArr[9] != null) {
							getNotificationService().sendNotificationToContractor((String) objArr[8],
									(String) objArr[9], (String) objArr[1]);
						}

					} catch (Exception e) {
						logger.error("An exception occurred.", e);
						logger.error("trying to insert with duplicate emailId with" + (String) objArr[8]);

					}

				}
			}
		}

	}

	@Override
	public List<WorkPhysicalMileStoneBean> fetchPhysicalMilestonesByWorkId(Long workId) {
		List<WorkPhysicalMileStone> workPhysicalMileStoneList = new LinkedList<WorkPhysicalMileStone>();
		List<WorkPhysicalMileStoneBean> workPhysicalMileStoneBeanList = new LinkedList<WorkPhysicalMileStoneBean>();
		if (null != workId) {
			WorkAgreement workAgreement = workAgreementRepository.findByWorkOrderByCreatedDateDesc(new Work(workId))
					.size() > 0 ? workAgreementRepository.findByWorkOrderByCreatedDateDesc(new Work(workId)).get(0)
							: null;
			if (null != workAgreement) {
				workPhysicalMileStoneList = workPhysicalMileStoneRepository
						.findByWorkAgreementAndWorkAgreementRevisionIsNull(workAgreement);
			}
		} else {
			workPhysicalMileStoneList = workPhysicalMileStoneRepository.fetchPhyMileByWorkAgreementRevisionIsNull();
		}
		for (WorkPhysicalMileStone d : workPhysicalMileStoneList) {
			WorkPhysicalMileStoneBean workPhysicalMileStoneBean = convertWorkPhysicalMileStoneEntityToWorkPhysicalMileStoneBean(
					d);
			workPhysicalMileStoneBeanList.add(workPhysicalMileStoneBean);
		}
		return workPhysicalMileStoneBeanList;
	}

