	private BillBean convertBillEntityToBeanForViewBill(Bill entity) {
		BillBean bean = new BillBean();

		if (entity != null) {
			bean.setId(entity.getId());
			bean.setBillNo(entity.getBillNo());
			bean.setBillDate(RESUtil.convertDateToString(entity.getBillDate()));
			bean.setBillType(entity.getBillType());
			bean.setBillAmount(entity.getBillAmount());
			bean.setMbNo(entity.getMbNo());
			bean.setMbPageNo(entity.getMbPageNo());

			if (bean.getMeasurementById() != null) {
				entity.setMeasurementBy(new Users(bean.getMeasurementById()));
			}

			bean.setSecurityDeposit(entity.getSecurityDeposit());
			bean.setIncomeTax(entity.getIncomeTax());
			bean.setUpkar(entity.getUpkar());
			bean.setRoyalty(entity.getRoyalty());
			bean.setOther(entity.getOther());
			bean.setCostOfBillForm(entity.getCostOfBillForm());
			bean.setStatusId(entity.getStatus().getStatusId());
			bean.setStatus(entity.getStatus().getStatusNameE());
			bean.setBillIndex(entity.getBillIndex());
			// Uncomment bean.setWork(convertWorkEntityToBean(entity.getWork()));
			bean.setWorkRequisitionNo(entity.getWork().getWorkRequisitionNo());
			bean.setWorkName(entity.getWork().getWorkName());

			bean.setCreatedBy(entity.getCreatedBy());
			/*
			 * if(entity.getInspectedByDatetime()!=null) {
			 * bean.setInspectedByDateTime(entity.getInspectedByDatetime()); }
			 * if(entity.getInspectedByEeDatetime()!=null) {
			 * bean.setInspectedByDateTimeEE(entity.getInspectedByEeDatetime()); }
			 */

			/*
			 * if(entity.getInspectedByDatetime()!=null) {
			 * bean.setInspectedByDateTimeString(RESUtil
			 * .convertDateToString(entity.getInspectedByDatetime())); }
			 * if(entity.getInspectedByEeDatetime()!=null) {
			 * bean.setInspectedByDateTimeEEString(RESUtil
			 * .convertDateToString(entity.getInspectedByEeDatetime())); }
			 */

			bean.setGst(entity.getGst());
			bean.setAddOthers(entity.getAddOthers());

			// Newly Added
			bean.setMiscDeposit(entity.getMiscDeposit());
			bean.setAdvancePayments(entity.getAdvancePayments());
			bean.setPerformanceGuarantee(entity.getPerformanceGuarantee());

			bean.setIsRevised(entity.getIsRevised());

			bean.setToShow(entity.getToShow());

			if (entity.getStatus() != null) {
				bean.setPrevStatusId(entity.getStatus().getStatusId());
				bean.setPrevstatus(entity.getStatus().getStatusNameE());
			}

			if (entity.getInspectedBy() != null) {
				bean.setInspectedBy(convertUserEntityToBean(entity.getInspectedBy()));
			}
			if (entity.getInspectedByEE() != null) {
				bean.setInspectedByEE(convertUserEntityToBean(entity.getInspectedByEE()));
			}

			if (entity.getMeasurementBy() != null) {
				bean.setMeasurementById(entity.getMeasurementBy().getId());
				bean.setMeasurementByBill(convertUserEntityToBean(entity.getMeasurementBy()));
			}

			if (null != entity.getInspectedByDatetime()) {
				bean.setInspectionDoneByAe(true);
			} else {
				bean.setInspectionDoneByAe(false);
			}

			if (null != entity.getInspectedByEeDatetime()) {
				bean.setInspectionDoneByEE(true);
			} else {
				bean.setInspectionDoneByEE(false);
			}
			if (entity.getContractorBillRemark() != null) {
				bean.setContractorBillRemark(entity.getContractorBillRemark());
			}
			if (entity.getSubeBillRemark() != null) {
				bean.setSubeBillRemark(entity.getSubeBillRemark());
			}

			if (entity.getEeBillRemark() != null) {
				bean.setEeBillRemark(entity.getEeBillRemark());
			}

			if (entity.getSdoRemark() != null) {
				bean.setSdoBillRemark(entity.getSdoRemark());
			}

			bean.setBillAmountWithoutDeduction(entity.getBillAmountWithoutDeduction());

			bean.setWorkId(entity.getWork().getId());
			bean.setWorkRequisitionNo(entity.getWork().getWorkRequisitionNo());

			bean.setWorkStatusId(entity.getWork().getWorkRequestStatusId().getId());
			bean.setWorkStatus(entity.getWork().getWorkRequestStatusId().getStatusNameE());
			if (entity.getStatus() != null && entity.getStatus().getStatusId() != null) {
				bean.setStatusId(entity.getStatus().getStatusId());
			}
		}

		return bean;
	}

	@Override
	public List<WorkNatureBean> fetchWorkNature() {

		try {
			List<WorkNature> list = workNatureRepository.findByEnabled((short) 1);

			List<WorkNatureBean> beanList = new ArrayList<>();
			for (WorkNature workNature : list) {
				beanList.add(convertWorkNatureEntityToBean(workNature));
			}
			return beanList;
		} catch (Exception e) {
			logger.error("An exception occurred.", e);
			return null;
		}

	}

	private WorkNatureBean convertWorkNatureEntityToBean(WorkNature entity) {

		WorkNatureBean bean = new WorkNatureBean();
		if (entity != null) {
			bean.setWorkNatureId(entity.getWorkNatureId());
			bean.setWorkNatureNameE(entity.getWorkNatureNameE());
			bean.setWorkNatureNameH(entity.getWorkNatureNameH());
			bean.setEnabled(entity.getEnabled());
		}
		return bean;
	}

