	@Override
	public Block getBlocks(UserBean userBean) {
		List<Office> officeList = officeRepository.findBlockIdById(userBean.getOfficeId());

		Block block = null;

		for (Office office : officeList) {
			System.out.println("Block Id: " + office.getBlockId().getBlockId());

			if (block == null) {
				block = office.getBlockId();
			}
		}
		return block;

	}

